1	"use strict";
2	// Run manager for POST /v2/run: queueing, spawning `claude -p` in stream-json mode,
3	// normalizing events, per-run replay buffer, SSE fan-out, abort.
4	
5	const { spawn } = require("child_process");
6	const crypto = require("crypto");
7	const fs = require("fs");
8	const path = require("path");
9	const { Normalizer } = require("./normalizer");
10	
11	const SLUG_RE = /^[a-z0-9][a-z0-9-]{0,47}$/;
12	const WORKTREE_RE = /^[a-z0-9][a-z0-9_-]{0,63}$/;
13	const RUN_ID_RE = /^[A-Za-z0-9._:-]{1,128}$/;
14	const SESSION_ID_RE = /^[A-Za-z0-9._-]{1,128}$/;
15	const MODEL_RE = /^[A-Za-z0-9._:\[\]\/@-]{1,128}$/;
16	const MODES = new Set(["auto", "edit", "plan", "ask"]);
17	const THINKING = { off: "0", normal: "8000", max: "32000" };
18	const EFFORTS = new Set(["low", "medium", "high", "xhigh", "max"]);
19	const AGENT_NAME_RE = /^[a-z0-9][a-z0-9-]{0,47}$/;
20	const AGENT_MODEL_RE = /^[A-Za-z0-9._:\[\]\/@-]{1,128}$/;
21	const TOOL_NAME_RE = /^[A-Za-z0-9_*:().\- ]{1,200}$/;
22	const AGENTS_INLINE_MAX = 32 * 1024; // larger --agents JSON goes through a temp file
23	// --autocompact takes the auto-compact *window* (100k-1M); compaction fires at window - 13k
24	// (CLI: threshold = min(window - 13000, window * PCT_OVERRIDE/100)).
25	const AUTOCOMPACT_MIN_WINDOW = 100_000;
26	const AUTOCOMPACT_MAX_WINDOW = 1_000_000;
27	const AUTOCOMPACT_BUFFER = 13_000;
28	
29	const EDIT_TOOLS = ["Read", "Edit", "Write", "Glob", "Grep", "Bash", "WebFetch", "WebSearch", "TodoWrite", "NotebookEdit", "TaskCreate", "TaskUpdate", "TaskGet", "TaskList"];
30	const ASK_TOOLS = ["Read", "Glob", "Grep", "WebFetch", "WebSearch", "TodoWrite", "TaskCreate", "TaskUpdate", "TaskGet", "TaskList"];
31	
32	const TERMINAL = new Set(["done", "error", "aborted"]);
33	const NEXUS_CWD_RE = /^\/[A-Za-z0-9._\/-]+$/;
34	
35	function isInside(child, parent) {
36	  const rel = path.relative(parent, child);
37	  return rel === "" || (!!rel && !rel.startsWith("..") && !path.isAbsolute(rel));
38	}
39	
40	/**
41	 * Build CLI args for a v2 run. `features` comes from parsing `claude --help`.
42	 */
43	function buildRunArgs(opts, features = {}, config = {}) {
44	  const args = ["-p", "--output-format", "stream-json", "--verbose", "--include-partial-messages"];
45	  if (features.permissionPrompts !== false) args.push("--permission-prompts", "none");
46	  if (opts.model) args.push("--model", opts.model);
47	  if (opts.sessionId) args.push("--resume", opts.sessionId);
48	  if (opts.maxTurns) args.push("--max-turns", String(opts.maxTurns));
49	  // Effort drives thinking depth and verbosity: keep simple requests cheap.
50	  const EFFORT = { off: "low", normal: "medium", max: "high" };
51	  const effort = opts.effort || (features.effort !== false ? EFFORT[opts.thinking || "normal"] : null);
52	  if (effort) args.push("--effort", effort);
53	  // Newer CLIs hide thinking text unless asked; summarized display streams readable thinking deltas.
54	  if (opts.thinking !== "off" && config.thinkingDisplay) args.push("--thinking-display", config.thinkingDisplay);
55	  if (opts.appendSystemPromptFile) args.push("--append-system-prompt-file", opts.appendSystemPromptFile);
56	  else if (opts.appendSystemPrompt) args.push("--append-system-prompt", opts.appendSystemPrompt);
57	  // Extra readable dirs: the attachments dir (sandbox home uploads or the shared uploads dir) + any granted dirs.
58	  const addDirs = opts.addDirsResolved || [...(config.uploadsDir ? [config.uploadsDir] : []), ...(opts.addDirs || [])];
59	  for (const d of addDirs) args.push("--add-dir", d);
60	  const ac = autocompactPlan(opts.autocompactTokens);
61	  if (ac && features.autocompact !== false) args.push("--autocompact", String(ac.window));
62	  const hasAgents = !!(opts.agents && Object.keys(opts.agents).length);
63	  if (hasAgents) args.push("--agents", opts.agentsFile || JSON.stringify(opts.agents));
64	  if (opts.agent) args.push("--agent", opts.agent);
65	  if (features.forwardSubagentText && config.forwardSubagentText !== false) args.push("--forward-subagent-text");
66	
67	  const modes = features.permissionModes || null; // null = unknown, assume all
68	  const has = (m) => !modes || modes.includes(m);
69	  switch (opts.mode || "auto") {
70	    case "auto": {
71	      const wanted = config.autoPermissionMode || "bypassPermissions";
72	      args.push("--permission-mode", has(wanted) ? wanted : "bypassPermissions");
73	      break;
74	    }
75	    case "edit":
76	      // Custom subagents are only useful in edit mode if the Agent tool is pre-approved.
77	      args.push("--permission-mode", "acceptEdits", "--allowedTools", ...EDIT_TOOLS, ...(hasAgents ? ["Agent"] : []));
78	      break;
79	    case "plan":
80	      args.push("--permission-mode", "plan");
81	      break;
82	    case "ask":
83	      if (has("dontAsk")) args.push("--permission-mode", "dontAsk");
84	      args.push("--tools", ASK_TOOLS.join(","), "--allowedTools", ...ASK_TOOLS);
85	      break;
86	  }
87	  // Sandboxed runs read the prompt from stdin so it never shows up in other uids' `ps` / /proc/<pid>/cmdline.
88	  if (!opts.promptViaStdin) args.push("--", opts.fullPrompt ?? opts.prompt);
89	  return args;
90	}
91	
92	/**
93	 * Map a desired auto-compact *threshold* (tokens of context at which compaction fires) to CLI settings.
94	 * Returns null for "CLI default" (0 / null). Thresholds below 87k use the minimum window (100k) plus
95	 * CLAUDE_AUTOCOMPACT_PCT_OVERRIDE (percent of the window).
96	 */
97	function autocompactPlan(tokens) {
98	  if (!tokens) return null;
99	  const want = tokens + AUTOCOMPACT_BUFFER;
100	  if (want >= AUTOCOMPACT_MIN_WINDOW) return { window: Math.min(AUTOCOMPACT_MAX_WINDOW, want), pct: null };
101	  return { window: AUTOCOMPACT_MIN_WINDOW, pct: Math.round((tokens / AUTOCOMPACT_MIN_WINDOW) * 1000) / 10 };
102	}
103	
104	function validateAgents(raw) {
105	  if (raw == null) return { agents: null };
106	  if (typeof raw !== "object" || Array.isArray(raw)) return { error: "Invalid agents (object expected)" };
107	  const names = Object.keys(raw);
108	  if (names.length > 100) return { error: "Too many agents" };
109	  const out = {};
110	  for (const name of names) {
111	    const a = raw[name];
112	    if (!AGENT_NAME_RE.test(name)) return { error: `Invalid agent name: ${name}` };
113	    if (!a || typeof a !== "object") return { error: `Invalid agent: ${name}` };
114	    if (typeof a.description !== "string" || !a.description.trim() || a.description.length > 4000) return { error: `Agent ${name}: invalid description` };
115	    if (typeof a.prompt !== "string" || !a.prompt.trim() || a.prompt.length > 100_000) return { error: `Agent ${name}: invalid prompt` };
116	    const def = { description: a.description, prompt: a.prompt };
117	    if (a.tools != null) {
118	      if (!Array.isArray(a.tools) || a.tools.length > 100 || !a.tools.every((t) => typeof t === "string" && TOOL_NAME_RE.test(t)))
119	        return { error: `Agent ${name}: invalid tools` };
120	      def.tools = a.tools;
121	    }
122	    if (a.model != null && a.model !== "") {
123	      if (typeof a.model !== "string" || !AGENT_MODEL_RE.test(a.model)) return { error: `Agent ${name}: invalid model` };
124	      def.model = a.model;
125	    }
126	    out[name] = def;
127	  }
128	  return { agents: out };
129	}
130	
131	function buildPrompt(prompt, attachments) {
132	  let out = prompt || "";
133	  if (attachments && attachments.length) {
134	    const lines = attachments.map((a) => `[Attached file: ${a} — use Read tool]`);
135	    out = out ? `${out}\n\n${lines.join("\n")}` : lines.join("\n");
136	  }
137	  return out;
138	}
