140	function buildChildEnv(baseEnv, opts) {
141	  const env = { ...baseEnv };
142	  delete env.CLAUDEBOX_API_KEY;
143	  delete env.PORT; // never leak the API server's PORT to Claude's shell
144	  if (opts.authToken) {
145	    if (opts.authToken.startsWith("sk-ant-api")) {
146	      env.ANTHROPIC_API_KEY = opts.authToken;
147	      delete env.CLAUDE_CODE_OAUTH_TOKEN;
148	    } else {
149	      env.CLAUDE_CODE_OAUTH_TOKEN = opts.authToken;
150	      delete env.ANTHROPIC_API_KEY;
151	    }
152	  }
153	  if (opts.thinking && THINKING[opts.thinking] !== undefined) env.MAX_THINKING_TOKENS = THINKING[opts.thinking];
154	  const ac = autocompactPlan(opts.autocompactTokens);
155	  if (ac && ac.pct != null) env.CLAUDE_AUTOCOMPACT_PCT_OVERRIDE = String(ac.pct);
156	  else delete env.CLAUDE_AUTOCOMPACT_PCT_OVERRIDE;
157	  if (opts.previewPort) {
158	    env.PORT = String(opts.previewPort);
159	    env.HOST = "0.0.0.0";
160	    env.BASE_PATH = `/preview/${opts.previewKey || opts.projectSlug}/`;
161	    env.NXEON_PREVIEW_PORT = String(opts.previewPort);
162	  }
163	  env.NXEON_PROJECT_SLUG = opts.projectSlug;
164	  env.NXEON_RUN_ID = opts.runId;
165	  return env;
166	}
