168	/**
169	 * Copy by creating a NEW file (not copyfile(), which carries the source's group/mode over): the copy then
170	 * inherits the setgid group + default ACLs of the sandbox home, i.e. it is readable by that sandbox only.
171	 */
172	function copyIntoSandbox(src, dest) {
173	  const tmp = `${dest}.part-${process.pid}`;
174	  const inFd = fs.openSync(src, "r");
175	  let outFd = null;
176	  try {
177	    outFd = fs.openSync(tmp, "w", 0o640);
178	    const buf = Buffer.allocUnsafe(1024 * 1024);
179	    for (;;) {
180	      const n = fs.readSync(inFd, buf, 0, buf.length, null);
181	      if (!n) break;
182	      fs.writeSync(outFd, buf, 0, n);
183	    }
184	    fs.closeSync(outFd);
185	    outFd = null;
186	    fs.renameSync(tmp, dest);
187	  } finally {
188	    fs.closeSync(inFd);
189	    if (outFd !== null) fs.closeSync(outFd);
190	    fs.rmSync(tmp, { force: true });
191	  }
192	}
193	
194	/** Project slugs of a Nexus run's addDirs (main checkouts and .branches/<slug>/<worktree>). */
195	function nexusSlugs(addDirs, projectsDir) {
196	  const out = new Set();
197	  for (const d of addDirs || []) {
198	    const seg = path.relative(projectsDir, d).split(path.sep);
199	    const slug = seg[0] === ".branches" ? seg[1] : seg[0];
200	    if (slug && SLUG_RE.test(slug)) out.add(slug);
201	  }
202	  return [...out];
203	}
204	
205	class RunManager {
206	  constructor(config) {
207	    this.config = {
208	      claudeBin: "claude",
209	      projectsDir: "/workspace/projects",
210	      uploadsDir: "/workspace/uploads",
211	      maxConcurrent: 4,
212	      retentionMs: 30 * 60 * 1000,
213	      maxEventsPerRun: 50000,
214	      killGraceMs: 4000,
215	      heartbeatMs: 15000,
216	      previewPortMin: 4100,
217	      previewPortMax: 4199,
218	      autoPermissionMode: "bypassPermissions",
219	      thinkingDisplay: "summarized",
220	      forwardSubagentText: true,
221	      log: () => {},
222	      features: () => ({}),
223	      env: process.env,
224	      ...config,
225	    };
226	    this.runs = new Map();
227	    this.queue = [];
228	    this.running = 0;
229	    this._gc = setInterval(() => this.gc(), 60 * 1000);
230	    this._gc.unref();
231	  }
232	
233	  close() {
234	    clearInterval(this._gc);
235	    for (const run of this.runs.values()) {
236	      for (const sub of run.subscribers) clearInterval(sub.hb);
237	      if (run.status === "running") this._kill(run, "SIGKILL", { sync: true });
238	    }
239	  }
240	
241	  /** Validate a /v2/run body. Returns {opts} or {error}. */
242	  validate(body) {
243	    const c = this.config;
244	    if (!body || typeof body !== "object") return { error: "Body must be a JSON object" };
245	    const runId = body.runId == null ? crypto.randomUUID() : body.runId;
246	    if (typeof runId !== "string" || !RUN_ID_RE.test(runId)) return { error: "Invalid runId" };
247	    if (typeof body.prompt !== "string") return { error: "Missing 'prompt' (string)" };
248	    if (body.prompt.length > 1_000_000) return { error: "Prompt too large" };
249	    if (typeof body.projectSlug !== "string" || !SLUG_RE.test(body.projectSlug))
250	      return { error: "Invalid projectSlug (must match ^[a-z0-9][a-z0-9-]{0,47}$)" };
251	    const sessionId = body.sessionId == null || body.sessionId === "" ? null : body.sessionId;
252	    if (sessionId !== null && (typeof sessionId !== "string" || !SESSION_ID_RE.test(sessionId))) return { error: "Invalid sessionId" };
253	    const model = body.model == null || body.model === "" ? null : body.model;
254	    if (model !== null && (typeof model !== "string" || !MODEL_RE.test(model))) return { error: "Invalid model" };
255	    const mode = body.mode == null ? "auto" : body.mode;
256	    if (!MODES.has(mode)) return { error: "Invalid mode (auto|edit|plan|ask)" };
257	    const thinking = body.thinking == null ? null : body.thinking;
258	    if (thinking !== null && THINKING[thinking] === undefined) return { error: "Invalid thinking (off|normal|max)" };
259	    const effort = body.effort == null ? null : body.effort;
260	    if (effort !== null && !EFFORTS.has(effort)) return { error: "Invalid effort" };
261	    let maxTurns = null;
262	    if (body.maxTurns != null) {
263	      maxTurns = Number(body.maxTurns);
264	      if (!Number.isInteger(maxTurns) || maxTurns < 1 || maxTurns > 1000) return { error: "Invalid maxTurns" };
265	    }
266	    let previewPort = null;
267	    if (body.previewPort != null) {
268	      previewPort = Number(body.previewPort);
269	      if (!Number.isInteger(previewPort) || previewPort < c.previewPortMin || previewPort > c.previewPortMax)
270	        return { error: `Invalid previewPort (${c.previewPortMin}-${c.previewPortMax})` };
271	    }
272	    const appendSystemPrompt = body.appendSystemPrompt == null ? null : body.appendSystemPrompt;
273	    if (appendSystemPrompt !== null && (typeof appendSystemPrompt !== "string" || appendSystemPrompt.length > 200_000))
274	      return { error: "Invalid appendSystemPrompt" };
275	    const authToken = body.authToken == null || body.authToken === "" ? null : body.authToken;
276	    if (authToken !== null && (typeof authToken !== "string" || authToken.length > 8192 || /[\r\n\0]/.test(authToken)))
277	      return { error: "Invalid authToken" };
278	
279	    let autocompactTokens = null;
280	    if (body.autocompactTokens != null && body.autocompactTokens !== 0) {
281	      autocompactTokens = Number(body.autocompactTokens);
282	      if (!Number.isInteger(autocompactTokens) || autocompactTokens < 10_000 || autocompactTokens > AUTOCOMPACT_MAX_WINDOW - AUTOCOMPACT_BUFFER)
283	        return { error: "Invalid autocompactTokens (0 or 10000-987000)" };
284	    }
285	    const va = validateAgents(body.agents);
286	    if (va.error) return { error: va.error };
287	    const agents = va.agents && Object.keys(va.agents).length ? va.agents : null;
288	    const agent = body.agent == null || body.agent === "" ? null : body.agent;
289	    if (agent !== null && (typeof agent !== "string" || !AGENT_NAME_RE.test(agent))) return { error: "Invalid agent" };
290	    if (agent !== null && agents && !agents[agent]) return { error: `Lead agent "${agent}" is not in agents` };
291	
292	    // Branch runs execute in the branch's git worktree (.branches/<slug>/<worktree>); preview key <slug>--<worktree>.
293	    const worktree = body.worktree == null || body.worktree === "" ? null : body.worktree;
294	    if (worktree !== null && (typeof worktree !== "string" || !WORKTREE_RE.test(worktree))) return { error: "Invalid worktree" };
295	    let cwd = worktree ? path.join(c.projectsDir, ".branches", body.projectSlug, worktree) : path.join(c.projectsDir, body.projectSlug);
296	    if (worktree && !fs.existsSync(cwd)) return { error: `Branch worktree '${worktree}' not found` };
297	
298	    // ---- sandbox identity (computed by the app; only ranges/paths are validated here) ----
299	    const sb = c.sandbox || null;
300	    let sandbox = null;
301	    let nexus = false;
302	    const addDirs = [];
303	    if (sb) {
304	      const v = sb.validateSpec(body.sandbox);
305	      if (v.error) return { error: v.error };
306	      sandbox = v.spec;
307	      if (body.cwd != null && body.cwd !== "") {
308	        // Multi-project ("Nexus") runs: cwd is a per-user scratch dir; projects are reached via groups + addDirs.
309	        const nx = sb.config.nexusDir;
310	        if (!sandbox) return { error: "cwd requires a sandbox spec" };
311	        if (typeof body.cwd !== "string" || !NEXUS_CWD_RE.test(body.cwd) || body.cwd.split("/").some((x) => x === ".." || x === ".") || !isInside(body.cwd, nx) || body.cwd === nx)
312	          return { error: `cwd must be inside ${nx}` };
313	        cwd = path.resolve(body.cwd);
314	        nexus = true;
315	      } else if (!sandbox) {
316	        sandbox = sb.specFromDir(body.projectSlug);
317	      } else {
318	        const fromDir = sb.specFromDir(body.projectSlug);
319	        if (fromDir && !sandbox.groups.includes(fromDir.gid)) return { error: `Sandbox has no access to project '${body.projectSlug}'` };
320	      }
321	      if (body.addDirs != null) {
322	        if (!Array.isArray(body.addDirs) || body.addDirs.length > 64) return { error: "Invalid addDirs" };
323	        for (const d of body.addDirs) {
324	          if (typeof d !== "string" || !NEXUS_CWD_RE.test(d) || d.split("/").some((x) => x === ".." || x === ".")) return { error: `Invalid addDir: ${d}` };
325	          const r = path.resolve(d);
326	          if (!isInside(r, c.projectsDir) || r === c.projectsDir || path.relative(c.projectsDir, r).startsWith(".trash")) return { error: `addDirs must be project dirs: ${d}` };
327	          addDirs.push(r);
328	        }
329	      }
330	      if (sb.strict && !sandbox) return { error: "Project sandbox is not set up (pass `sandbox` or run /v2/sandbox/setup)", status: 409 };
331	    } else if (body.cwd != null && body.cwd !== "") {
332	      return { error: "cwd is only supported with sandboxing" };
333	    }
334	    const previewKey = worktree ? `${body.projectSlug}--${worktree}` : body.projectSlug;
335	    const attachments = [];
336	    if (body.attachments != null) {
337	      if (!Array.isArray(body.attachments) || body.attachments.length > 100) return { error: "Invalid attachments" };
338	      for (const a of body.attachments) {
339	        if (typeof a !== "string" || /[\r\n\0]/.test(a)) return { error: "Invalid attachment path" };
340	        const resolved = path.resolve(a);
341	        if (!isInside(resolved, c.uploadsDir) && !isInside(resolved, cwd))
342	          return { error: `Attachment must be under ${c.uploadsDir} or the project dir: ${a}` };
343	        attachments.push(resolved);
344	      }
345	    }
346	    if (!body.prompt.trim() && !attachments.length) return { error: "Empty prompt" };
347	
348	    return {
349	      opts: {
350	        runId, prompt: body.prompt, projectSlug: body.projectSlug, worktree, previewKey, cwd, sessionId, model, mode, thinking,
351	        effort, attachments, appendSystemPrompt, maxTurns, previewPort, authToken, autocompactTokens, agents, agent,
352	        sandbox, nexus, addDirs,
353	        fullPrompt: buildPrompt(body.prompt, attachments),
354	      },
355	    };
356	  }
357	
358	  get(runId) {
359	    return this.runs.get(runId) || null;
360	  }
361	
362	  create(opts) {
363	    if (this.runs.has(opts.runId)) {
364	      const err = new Error(`Run ${opts.runId} already exists`);
365	      err.code = "RUN_EXISTS";
366	      throw err;
367	    }
368	    if (!(this.config.sandbox && this.config.sandbox.strict && opts.sandbox)) fs.mkdirSync(opts.cwd, { recursive: true });
369	    const run = {
370	      runId: opts.runId,
371	      projectSlug: opts.projectSlug,
372	      cwd: opts.cwd,
373	      sandbox: opts.sandbox || null,
374	      mode: opts.mode,
375	      model: opts.model,
376	      opts,
377	      status: "queued",
378	      createdAt: Date.now(),
379	      startedAt: null,
380	      endedAt: null,
381	      exitCode: null,
382	      sessionId: opts.sessionId || null,
383	      events: [],
384	      nextSeq: 1,
385	      subscribers: new Set(),
386	      proc: null,
387	      pid: null,
388	      aborted: false,
389	      stderrTail: "",
390	      finished: false,
391	    };
392	    this.runs.set(run.runId, run);
393	    this.queue.push(run);
394	    this.config.log("info", "run queued", { runId: run.runId, projectSlug: run.projectSlug, mode: run.mode, model: run.model });
395	    this._pump();
396	    return run;
397	  }
398	
399	  _pump() {
400	    while (this.running < this.config.maxConcurrent && this.queue.length) {
401	      const run = this.queue.shift();
402	      if (run.status !== "queued") continue;
403	      this._start(run);
404	    }
405	  }
406	
407	  _push(run, type, data) {
408	    if (type === "__internal_error") {
409	      this.config.log("warn", "normalizer error", { runId: run.runId, ...data });
410	      return;
411	    }
412	    if (type === "init" && data.sessionId) run.sessionId = data.sessionId;
413	    if (type === "result" && data.sessionId) run.sessionId = data.sessionId;
414	    const ev = { seq: run.nextSeq++, type, data };
415	    run.events.push(ev);
416	    const max = this.config.maxEventsPerRun;
417	    if (run.events.length > max * 1.1) run.events.splice(0, run.events.length - max);
418	    const frame = sseFrame(ev);
419	    for (const sub of run.subscribers) {
420	      try {
421	        sub.res.write(frame);
422	      } catch {
423	        /* ignore */
424	      }
425	    }
426	  }
427	
428	  /**
429	   * Sandboxed runs: per-run files live in the sandbox home (readable by the run's uid only), attachments are
430	   * copied into <home>/uploads/<uploadId>/ so a run never sees other users' uploads, and the prompt goes via stdin.
431	   */
432	  _prepareSandboxed(run) {
433	    const c = this.config;
434	    const opts = run.opts;
435	    const spec = opts.sandbox;
436	    const home = spec.home;
