217	      costUsd: 0, sessionCostUsd: null, durationMs: null, sawResult: false, resultIsError: false, resultText: '', sawError: false,
218	      lastError: null, exitCode: undefined, abortRequested: false, ended: false, controller: new AbortController(),
219	      startedAt: now(),
220	      kind: null,
221	      branch: null,
222	      nexus: null,
223	      mode: null,
224	    };
225	  }
