240	
241	  /** Connects (or re-attaches) to claudebox and consumes the stream until `done` or give-up. */
242	  private async drive(run: ActiveRun, recovering: boolean) {
243	    if (!recovering) {
244	      this.setStatus(run, 'running');
245	      if (run.projectId) this.db.prepare(`UPDATE projects SET last_active_at = ? WHERE id = ?`).run(now(), run.projectId);
246	    }
247	    let attempt = 0;
248	    let first = !recovering;
249	    while (!run.ended) {
250	      if (run.abortRequested && first) {
251	        this.synthEnd(run, null);
252	        return;
253	      }
254	      let res: Dispatcher.ResponseData;
255	      try {
256	        res = first ? await this.cb.startRun(run.body!, run.controller.signal) : await this.cb.attach(run.id, run.upstreamSeq + 1, run.controller.signal);
257	      } catch (err) {
258	        if (run.ended) return;
259	        if (run.abortRequested) {
260	          this.synthEnd(run, null);
261	          return;
262	        }
263	        if (first) {
264	          this.emit(run, 'error', { message: `Cannot reach claudebox: ${(err as Error).message}` });
265	          this.synthEnd(run, null);
266	          return;
267	        }
268	        if (++attempt > (recovering ? 2 : MAX_REATTACH)) {
269	          this.emit(run, 'error', { message: 'Lost connection to the Claude runner.' });
270	          this.synthEnd(run, null);
271	          return;
272	        }
273	        await sleep(Math.min(8000, 500 * 2 ** attempt));
274	        continue;
275	      }
276	      const wasFirst = first;
277	      first = false;
278	      if (res.statusCode !== 200) {
279	        const text = (await res.body.text().catch(() => '')).slice(0, 500);
280	        if (run.ended) return;
281	        if (!wasFirst && res.statusCode === 404) {
282	          this.emit(run, 'error', { message: recovering ? 'The run was lost while the server restarted.' : 'Lost connection to the Claude runner (run no longer available).' });
283	        } else {
284	          let msg = text;
285	          try {
286	            const j = JSON.parse(text) as { error?: unknown; message?: unknown };
287	            const e = j.error ?? j.message;
288	            msg = typeof e === 'string' ? e : (e as { message?: string })?.message ?? text;
289	          } catch {
290	            /* plain text */
291	          }
292	          this.emit(run, 'error', { message: `Claude runner error (${res.statusCode}): ${msg || 'unknown error'}` });
293	        }
294	        this.synthEnd(run, null);
295	        return;
296	      }
297	      attempt = 0;
298	      try {
299	        await this.consume(run, res.body);
300	      } catch (err) {
301	        if (run.ended) return;
302	        this.log.warn({ runId: run.id, err: (err as Error).message }, 'run stream interrupted');
303	      }
304	      if (run.ended) return;
305	      if (run.abortRequested && run.controller.signal.aborted) {
306	        this.synthEnd(run, null);
307	        return;
308	      }
309	      // Stream ended without `done` → reattach with backoff.
310	      if (++attempt > MAX_REATTACH) {
311	        this.emit(run, 'error', { message: 'Lost connection to the Claude runner.' });
312	        this.synthEnd(run, null);
313	        return;
314	      }
315	      await sleep(Math.min(8000, 300 * 2 ** attempt));
316	    }
317	  }
318	
319	  private async consume(run: ActiveRun, body: Dispatcher.ResponseData['body']) {
320	    const parser = new SseParser();
321	    body.setEncoding('utf8');
322	    for await (const chunk of body) {
323	      for (const m of parser.push(chunk as string)) {
324	        this.handleUpstream(run, m);
325	        if (run.ended) {
326	          body.destroy();
327	          return;
328	        }
329	      }
330	    }
331	  }
332	
333	  handleUpstream(run: ActiveRun, m: SseMessage) {
334	    if (m.id !== undefined && /^\d+$/.test(m.id)) {
335	      const id = Number(m.id);
336	      if (id <= run.upstreamSeq) return; // duplicate after reattach
337	      run.upstreamSeq = id;
338	    }
339	    const type = m.event as RunEventType;
340	    if (!KNOWN_TYPES.has(type)) return;
341	    let data: Record<string, unknown>;
342	    try {
343	      data = (m.data ? JSON.parse(m.data) : {}) as Record<string, unknown>;
344	    } catch {
345	      return;
346	    }
347	    switch (type) {
348	      case 'init': {
349	        const sid = typeof data.sessionId === 'string' ? data.sessionId : null;
350	        if (sid) this.db.prepare(`UPDATE conversations SET claude_session_id = ? WHERE id = ?`).run(sid, run.conversationId);
351	        this.emit(run, 'init', data);
352	        break;
353	      }
354	      case 'text': {
355	        if (typeof data.parentId === 'string') {
356	          // forwarded subagent text: shown under the delegating tool, never part of the answer
357	          this.emit(run, 'text', data);
358	          break;
359	        }
360	        let delta = typeof data.delta === 'string' ? data.delta : '';
361	        if (!delta) return;
362	        if (run.needSep && run.fullText.length && !/\n\s*$/.test(run.fullText)) delta = '\n\n' + delta;
363	        run.needSep = false;
364	        run.fullText += delta;
365	        this.emitVisible(run, true);
366	        break;
367	      }
368	      case 'block_end': {
369	        if (data.kind === 'text') {
370	          this.emitVisible(run, false);
371	          run.needSep = true;
372	        }
373	        this.emit(run, 'block_end', data);
374	        break;
375	      }
376	      case 'usage': {
377	        const u = data as Partial<Usage>;
378	        run.usage.inputTokens += num(u.inputTokens);
379	        run.usage.outputTokens += num(u.outputTokens);
380	        run.usage.cacheReadTokens += num(u.cacheReadTokens);
381	        run.usage.cacheWriteTokens += num(u.cacheWriteTokens);
382	        if (!data.parentId && num(data.contextTokens) > 0) this.setContextTokens(run, num(data.contextTokens));
383	        this.emit(run, 'usage', data);
384	        break;
385	      }
386	      case 'compact': {
387	        this.setContextTokens(run, num(data.postTokens));
388	        this.emit(run, 'compact', data);
389	        break;
390	      }
391	      case 'result': {
392	        run.sawResult = true;
393	        run.resultIsError = !!data.isError;
394	        run.resultText = typeof data.result === 'string' ? data.result : '';
395	        const u = data.usage as Partial<Usage> | undefined;
396	        if (u && typeof u === 'object') {
397	          // result.usage covers the main thread only; the summed usage events also include subagents
398	          // (parentId) and estimated compaction usage — keep whichever is larger per field.
399	          run.usage = {
400	            inputTokens: Math.max(num(u.inputTokens), run.usage.inputTokens),
401	            outputTokens: Math.max(num(u.outputTokens), run.usage.outputTokens),
402	            cacheReadTokens: Math.max(num(u.cacheReadTokens), run.usage.cacheReadTokens),
403	            cacheWriteTokens: Math.max(num(u.cacheWriteTokens), run.usage.cacheWriteTokens),
404	          };
405	        }
406	        if (typeof data.costUsd === 'number') {
407	          // total_cost_usd is cumulative for the resumed session: charge this run only the increase.
408	          const prev = (this.db
409	            .prepare(`SELECT COALESCE(MAX(session_cost_usd), 0) AS v FROM runs WHERE conversation_id = ? AND id != ? AND started_at <= ?`)
410	            .get(run.conversationId, run.id, run.startedAt) as { v: number }).v;
411	          run.sessionCostUsd = data.costUsd;
412	          run.costUsd = data.costUsd >= prev ? data.costUsd - prev : data.costUsd;
413	        }
414	        if (typeof data.durationMs === 'number') run.durationMs = data.durationMs;
415	        if (typeof data.sessionId === 'string' && data.sessionId)
416	          this.db.prepare(`UPDATE conversations SET claude_session_id = ? WHERE id = ?`).run(data.sessionId, run.conversationId);
417	        if (run.resultIsError && run.resultText && !run.lastError) run.lastError = run.resultText;
418	        // The suggestions block lives in the final text; don't leak it through the result payload.
419	        this.emit(run, 'result', { ...data, result: finalContent(run.resultText) });
420	        break;
421	      }
422	      case 'error': {
423	        run.sawError = true;
424	        if (data.code === 'authentication_failed') {
425	          data = { ...data, detail: data.message, message: AUTH_HINT };
426	        }
427	        run.lastError = typeof data.message === 'string' ? data.message : 'error';
428	        this.emit(run, 'error', data);
429	        break;
430	      }
431	      case 'tool_use': {
432	        this.emit(run, 'tool_use', data);
433	        if (run.nexus && typeof data.name === 'string' && isWriteTool(data.name, data.input)) {
434	          for (const t of touchedPaths(this.cfg.claudeboxProjectsDir, data.name, data.input)) {
435	            const sp = run.nexus.projects.find((x) => x.slug === t.slug && (t.worktree ? x.worktree === t.worktree : true));
436	            if (sp) this.nexusTouch(run, sp.id, t.worktree ? sp.branch : null);
437	          }
438	        }
439	        break;
440	      }
441	      case 'done': {
442	        this.emitVisible(run, false);
443	        run.exitCode = typeof data.exitCode === 'number' ? data.exitCode : null;
444	        if (data.aborted === true) run.abortRequested = true;
445	        this.emit(run, 'done', { ...data, exitCode: run.exitCode });
446	        this.finalize(run);
447	        break;
448	      }
449	      default:
450	        this.emit(run, type, data);
451	    }
452	  }
