454	  private setContextTokens(run: ActiveRun, n: number) {
455	    if (!(n >= 0)) return;
456	    this.db.prepare(`UPDATE conversations SET context_tokens = ? WHERE id = ?`).run(Math.round(n), run.conversationId);
457	  }
458	
459	  private emitVisible(run: ActiveRun, holdPartial: boolean) {
460	    const vis = visibleText(run.fullText, holdPartial);
461	    if (vis.length > run.emittedLen) {
462	      this.emit(run, 'text', { delta: vis.slice(run.emittedLen) });
463	      run.emittedLen = vis.length;
464	    }
465	  }
466	
467	  private emit(run: ActiveRun, type: string, data: unknown) {
468	    const seq = ++run.seq;
469	    const ts = now();
470	    const ev: StoredEvent = { seq, type, data, ts };
471	    run.pending.push(ev);
472	    // `ts` is an additive field (not in protocol.ts) used by the UI for "Thought for Xs".
473	    this.hub.broadcastRun(run.id, { t: 'run_event', runId: run.id, seq, type, data, ts } as never);
474	    if (run.projectId) this.pulse(run.projectId, PULSE[type as RunEventType] ?? 0.2, run.branch);
475	    if (!this.flushTimer) this.flushTimer = setTimeout(() => this.flushAll(), FLUSH_MS);
476	  }
477	
478	  private pulse(projectId: string, intensity: number, branch: string | null = null, source?: 'nexus') {
479	    const t = Date.now();
480	    const k = `${projectId}|${branch ?? ''}|${source ?? ''}`;
481	    if (intensity < 0.8 && t - (this.lastPulse.get(k) ?? 0) < 250) return;
482	    if (source && t - (this.lastPulse.get(k) ?? 0) < 400) return;
483	    this.lastPulse.set(k, t);
484	    this.hub.broadcastViewers(projectId, { t: 'graph_pulse', projectId, intensity, branch, ...(source ? { source } : {}) });
485	  }
486	
487	  /** A Nexus run wrote to a project: light its strand from the core; record it (live `nexus` run event). */
488	  private nexusTouch(run: ActiveRun, projectId: string, branch: string | null) {
489	    if (!run.nexus || run.ended) return;
490	    this.pulse(projectId, 0.9, branch, 'nexus');
491	    if (run.nexus.touched.has(projectId)) return;
492	    run.nexus.touched.add(projectId);
493	    this.emit(run, 'nexus', { touched: [...run.nexus.touched] });
494	  }
495	
496	  /** File watcher hook: changes in a project checkout during an active Nexus run that has it in scope. */
497	  noteFileChange(projectId: string, branch: string | null) {
498	    for (const run of this.active.values()) {
499	      if (!run.nexus || run.ended) continue;
500	      if (run.nexus.projects.some((x) => x.id === projectId && x.branch === branch)) this.nexusTouch(run, projectId, branch);
501	    }
502	  }
503	
504	  flushAll() {
505	    if (this.flushTimer) {
506	      clearTimeout(this.flushTimer);
507	      this.flushTimer = null;
508	    }
509	    const tx = this.db.transaction(() => {
510	      for (const run of this.active.values()) this.flushRun(run);
511	    });
512	    try {
513	      tx();
514	    } catch (err) {
515	      this.log.error({ err }, 'flush run events failed');
516	    }
517	  }
518	
519	  private flushRun(run: ActiveRun) {
520	    if (!run.pending.length) return;
521	    for (const e of run.pending) this.insertEvent.run(run.id, e.seq, e.type, JSON.stringify(e.data ?? null), e.ts);
522	    run.pending = [];
523	    this.updateRunTotals.run(
524	      run.usage.inputTokens, run.usage.outputTokens, run.usage.cacheReadTokens, run.usage.cacheWriteTokens,
525	      run.costUsd, run.upstreamSeq, run.id,
526	    );
527	  }
528	
529	  /** Emit a synthetic `done` and finalize (used on errors / aborts without upstream completion). */
530	  private synthEnd(run: ActiveRun, exitCode: number | null) {
531	    if (run.ended) return;
532	    this.emitVisible(run, false);
533	    run.exitCode = exitCode;
534	    this.emit(run, 'done', { exitCode });
535	    this.finalize(run);
536	  }
537	
538	  private finalize(run: ActiveRun) {
539	    if (run.ended) return;
540	    run.ended = true;
541	    run.controller.abort();
542	    let status: RunStatus;
543	    if (run.abortRequested) status = 'aborted';
544	    else if (run.sawResult) status = run.resultIsError ? 'error' : 'done';
545	    else if (run.sawError) status = 'error';
546	    else status = run.exitCode === 0 ? 'done' : 'error';
547	
548	    let suggestions: Suggestion[] = parseSuggestions(run.fullText);
549	    if (!suggestions.length && run.resultText) suggestions = parseSuggestions(run.resultText);
550	    let handoffs: Handoff[] = [];
551	    if (run.nexus) {
552	      const slugs = new Set(run.nexus.projects.map((x) => x.slug));
553	      handoffs = parseHandoffs(run.fullText, slugs);
554	      if (!handoffs.length && run.resultText) handoffs = parseHandoffs(run.resultText, slugs);
555	    }
556	    let content = finalContent(run.fullText);
557	    if (!content && run.resultText) content = finalContent(run.resultText);
558	    const t = now();
559	    const durationMs = run.durationMs ?? t - run.startedAt;
560	
561	    this.db.transaction(() => {
562	      this.flushRun(run);
563	      this.updateRunTotals.run(
564	        run.usage.inputTokens, run.usage.outputTokens, run.usage.cacheReadTokens, run.usage.cacheWriteTokens,
565	        run.costUsd, run.upstreamSeq, run.id,
566	      );
567	      this.db
568	        .prepare(`UPDATE runs SET status = ?, ended_at = ?, duration_ms = ?, error = ?, session_cost_usd = ? WHERE id = ?`)
569	        .run(status, t, durationMs, status === 'error' ? (run.lastError ?? 'Run failed').slice(0, 2000) : null, run.sessionCostUsd, run.id);
570	      this.db
571	        .prepare(`UPDATE messages SET content = ?, suggestions = ?, handoffs = ? WHERE id = ?`)
572	        .run(content, suggestions.length ? JSON.stringify(suggestions) : null, handoffs.length ? JSON.stringify(handoffs) : null, run.assistantMessageId);
573	      this.db.prepare(`UPDATE conversations SET updated_at = ? WHERE id = ?`).run(t, run.conversationId);
574	      if (run.projectId) this.db.prepare(`UPDATE projects SET last_active_at = ? WHERE id = ?`).run(t, run.projectId);
575	    })();
576	    this.active.delete(run.id);
577	    if (suggestions.length) this.hub.broadcastRun(run.id, { t: 'suggestions', runId: run.id, items: suggestions });
578	    this.broadcastStatus(run, status);
579	    if (run.projectId) {
580	      this.pulse(run.projectId, 1, run.branch);
581	      if (status === 'done' && run.kind !== 'compact') {
582	        const pid = run.projectId;
583	        void this.checkpoint(run).finally(() => this.autoStartPreview(pid, run.branch));
584	      }
585	    } else if (run.nexus) {
586	      const writes = status === 'done' && run.kind !== 'compact' && run.mode !== 'ask' && run.mode !== 'plan';
587	      void (writes ? this.nexusCheckpoint(run) : Promise.resolve([] as NexusCommit[])).then((commits) => {
588	        this.markCheckpointed(run);
589	        if (run.userId)
590	          this.hub.broadcastUser(run.userId, {
591	            t: 'nexus_run', runId: run.id, conversationId: run.conversationId, touched: [...run.nexus!.touched], commits,
592	            handoffs: handoffs as NexusHandoff[], checkpointed: true,
593	          });
594	      });
595	    }
596	  }
597	
598	  private markCheckpointed(run: ActiveRun) {
599	    if (!run.nexus) return;
600	    const { touched: _t, ...scope } = run.nexus;
601	    this.db.prepare(`UPDATE runs SET nexus_scope = ? WHERE id = ?`).run(JSON.stringify({ ...scope, checkpointed: true }), run.id);
602	  }
603	
604	  /**
605	   * Nexus runs: commit a checkpoint in every in-scope checkout that changed ("git add -A" + commit only when dirty),
606	   * record them in nexus_run_commits (→ "Undo this run" across projects) and light up those projects.
607	   * Checkouts with an active project run are skipped (that run's own checkpoint will include the changes).
608	   */
609	  async nexusCheckpoint(run: ActiveRun): Promise<NexusCommit[]> {
610	    const scope = run.nexus;
611	    if (!scope) return [];
612	    const prompt = run.body?.prompt
613	      ?? (this.db.prepare(`SELECT content FROM messages WHERE run_id = ? AND role = 'user'`).get(run.id) as { content: string } | undefined)?.content
614	      ?? '';
615	    const line = prompt.replace(/\s+/g, ' ').trim().slice(0, 60) || 'run';
616	    const out: NexusCommit[] = [];
617	    const dirty = new Set(scope.dirty ?? []);
618	    const mixed: string[] = [];
619	    scope.mixed = mixed;
620	    // already-dirty, unfocused checkouts are only committed when the run demonstrably wrote there
621	    const queue = scope.projects.filter((x) => x.branch || !dirty.has(x.id) || scope.touched.has(x.id));
622	    const worker = async () => {
623	      for (let x = queue.shift(); x; x = queue.shift()) {
624	        try {
625	          const p = this.db.prepare(`SELECT * FROM projects WHERE id = ?`).get(x.id) as ProjectRow | undefined;
626	          if (!p || p.archived) continue;
627	          const b = x.branch ? getBranch(this.db, p.id, x.branch) : null;
628	          if (x.branch && !b) continue;
629	          const busy = this.db.prepare(`SELECT 1 FROM runs WHERE project_id = ? AND branch IS ? AND status IN ('queued','running')`).get(p.id, x.branch);
630	          if (busy) continue;
631	          const main = await ensureGit({ db: this.db, cb: this.cb, log: this.log }, p);
632	          const r = await this.cb.git<{ sha: string | null; files?: number; skipped?: string }>('checkpoint', {
633	            projectSlug: p.slug, ...(b ? { worktree: b.dir } : {}), message: `nxeon (nexus): ${line}`, expectBranch: b ? b.name : main,
634	          }, 30_000);
635	          if (r.skipped) this.log.warn({ runId: run.id, project: p.slug, skipped: r.skipped }, 'nexus checkpoint skipped');
636	          if (!r.sha) continue;
637	          if (!x.branch && dirty.has(p.id)) mixed.push(p.id);
638	          this.db
639	            .prepare(`INSERT OR REPLACE INTO nexus_run_commits(run_id, project_id, branch, sha, files, created_at) VALUES (?,?,?,?,?,?)`)
640	            .run(run.id, p.id, x.branch, r.sha, r.files ?? 0, now());
641	          this.db.prepare(`UPDATE projects SET last_active_at = ? WHERE id = ?`).run(now(), p.id);
642	          out.push({
643	            projectId: p.id, slug: p.slug, name: p.name, color: p.color, branch: x.branch, sha: r.sha, files: r.files ?? 0, undone: false,
644	            ...(!x.branch && dirty.has(p.id) ? { mixed: true } : {}),
645	          });
646	          scope.touched.add(p.id);
647	          this.hub.broadcastProject(p.id, { t: 'project_changed', projectId: p.id, what: 'history', branch: x.branch });
648	          this.pulse(p.id, 1, x.branch, 'nexus');
649	          void this.autoStartPreview(p.id, x.branch);
650	        } catch (err) {
651	          this.log.warn({ err: (err as Error).message, runId: run.id, project: x.slug }, 'nexus checkpoint failed');
652	        }
653	      }
654	    };
655	    await Promise.all(Array.from({ length: Math.min(4, queue.length) }, worker));
656	    return out;
657	  }
658	
659	  /** Auto-checkpoint: commit everything in the run's checkout as "nxeon: <prompt>" and record the sha on the run. */
660	  private async checkpoint(run: ActiveRun) {
661	    try {
662	      const p = this.db.prepare(`SELECT * FROM projects WHERE id = ?`).get(run.projectId) as ProjectRow | undefined;
663	      if (!p) return;
664	      const b = run.branch ? getBranch(this.db, p.id, run.branch) : null;
665	      if (run.branch && !b) return;
666	      const main = await ensureGit({ db: this.db, cb: this.cb, log: this.log }, p);
667	      const prompt = run.body?.prompt
668	        ?? (this.db.prepare(`SELECT content FROM messages WHERE run_id = ? AND role = 'user'`).get(run.id) as { content: string } | undefined)?.content
669	        ?? '';
670	      const line = prompt.replace(/\s+/g, ' ').trim().slice(0, 60) || 'run';
671	      const r = await this.cb.git<{ sha: string | null; skipped?: string }>('checkpoint', {
672	        projectSlug: p.slug, ...(b ? { worktree: b.dir } : {}), message: `nxeon: ${line}`, expectBranch: b ? b.name : main,
673	      });
674	      if (r.skipped) this.log.warn({ runId: run.id, skipped: r.skipped }, 'checkpoint skipped');
675	      if (r.sha) {
