/** The project's sandbox identity for claudebox (strict mode runs Claude as this uid). */
function sandboxBody(project: ProjectRow) {
  const sandbox = projectSandbox(project);
  return sandbox ? { sandbox } : {};
}

const MODES = ['auto', 'edit', 'plan', 'ask'] as const;
const modelSchema = z.string().trim().min(1).max(100).regex(/^[A-Za-z0-9._:\-[\]]+$/, 'invalid model id');
const createSchema = z.object({
  title: z.string().trim().max(200).optional(),
  model: modelSchema.optional(),
  mode: z.enum(MODES).optional(),
  /** branch name (null/absent = main) */
  branch: z.string().max(100).nullable().optional(),
  topicId: z.string().max(64).nullable().optional(),
});
const agentSlugSchema = z.string().trim().regex(AGENT_SLUG_RE, 'invalid agent').nullable();
const patchSchema = z.object({
  title: z.string().trim().min(1).max(200).optional(),
  model: modelSchema.optional(),
  mode: z.enum(MODES).optional(),
  agentSlug: agentSlugSchema.optional(),
  /** move to a topic (null = ungrouped) */
  topicId: z.string().max(64).nullable().optional(),
});
export const compactSchema = z.object({ instructions: z.string().max(4000).optional().default('') });
export const promptSchema = z.object({
  text: z.string().max(200_000).default(''),
  attachments: z.array(z.string().max(64)).max(20).default([]),
  model: modelSchema.optional(),
  mode: z.enum(MODES).optional(),
  thinking: z.enum(['off', 'normal', 'max']).optional().default('normal'),
  /** Lead agent for the conversation (persisted). null = default Claude; undefined = keep. */
  agent: agentSlugSchema.optional(),
  /** Nexus conversations: `#slug` / `#slug@branch` focus mentions (more detail in the index, branch worktrees added). */
  projects: z.array(z.string().max(120)).max(16).optional().default([]),
});
export type PromptBody = z.infer<typeof promptSchema>;

export const DEFAULT_TITLE = 'New conversation';

export function autoTitle(text: string): string {
  let s = text
    .replace(/```[\s\S]*?```/g, ' ')
    .replace(/[`*_#>~|[\]]+/g, ' ')
    .replace(/https?:\/\/\S+/g, (m) => m.replace(/^https?:\/\//, ''))
    .replace(/\s+/g, ' ')
    .trim();
  if (!s) return DEFAULT_TITLE;
  if (s.length > 60) {
    const cut = s.slice(0, 60);
    const sp = cut.lastIndexOf(' ');
    s = (sp > 30 ? cut.slice(0, sp) : cut).replace(/[\s,.;:!?-]+$/, '') + '…';
  }
  return s.charAt(0).toUpperCase() + s.slice(1);
}

export function startOfTodayUtc(): number {
  const d = new Date();
  return Date.UTC(d.getUTCFullYear(), d.getUTCMonth(), d.getUTCDate());
}

export function tokensUsedSince(ctx: Ctx, since: number, userId?: string): number {
  const r = (
    userId
      ? ctx.db.prepare(`SELECT COALESCE(SUM(input_tokens + output_tokens + cache_write), 0) AS n FROM runs WHERE user_id = ? AND started_at >= ?`).get(userId, since)
      : ctx.db.prepare(`SELECT COALESCE(SUM(input_tokens + output_tokens + cache_write), 0) AS n FROM runs WHERE started_at >= ?`).get(since)
  ) as { n: number };
  return r.n;
}

export function effectiveDailyLimit(ctx: Ctx, u: UserRow): number | null {
  return u.daily_tokens ?? ctx.settings.get().defaultUserDailyTokens ?? null;
}

/** Model/mode permissions, daily budgets and the one-run-per-conversation rule (throws 429/409). */
export function assertRunAllowed(ctx: Ctx, u: UserRow, conv: ConversationRow, model: string, mode: Mode) {
  const s = ctx.settings.get();
  const allowedModels = u.allowed_models ? (JSON.parse(u.allowed_models) as string[]) : null;
  if (allowedModels && allowedModels.length && !allowedModels.includes(model))
    throw new HttpError(429, 'model_limit', `You are not allowed to use model "${model}"`);
  if (!allowedModels && u.role !== 'admin' && !s.models.some((m) => m.id === model))
    throw new HttpError(429, 'model_limit', `Model "${model}" is not enabled`);
  const allowedModes = u.allowed_modes ? (JSON.parse(u.allowed_modes) as Mode[]) : null;
  if (allowedModes && allowedModes.length && !allowedModes.includes(mode))
    throw new HttpError(429, 'mode_limit', `You are not allowed to use ${mode} mode`);
  const today = startOfTodayUtc();
  const limit = effectiveDailyLimit(ctx, u);
  if (limit != null && tokensUsedSince(ctx, today, u.id) >= limit)
    throw new HttpError(429, 'daily_token_limit', 'Daily token budget reached. It resets at 00:00 UTC.');
  if (s.globalDailyTokens != null && tokensUsedSince(ctx, today) >= s.globalDailyTokens)
    throw new HttpError(429, 'global_token_limit', 'The workspace-wide daily token cap has been reached.');
  if (ctx.runs.activeForConversation(conv.id) || ctx.db.prepare(`SELECT 1 FROM runs WHERE conversation_id = ? AND status IN ('queued','running')`).get(conv.id))
    throw conflict('A run is already in progress in this conversation', 'run_in_progress');
}

function checkTopic(ctx: Ctx, projectId: string, topicId: string | null | undefined) {
  if (!topicId) return;
  if (!ctx.db.prepare(`SELECT 1 FROM topics WHERE id = ? AND project_id = ?`).get(topicId, projectId)) throw badRequest('Unknown topic', 'unknown_topic');
}

/** The conversation's branch row (null = main); 409 if that branch was closed meanwhile. */
function convBranch(ctx: Ctx, conv: ConversationRow): BranchRow | null {
  if (!conv.branch || !conv.project_id) return null;
  const b = getBranch(ctx.db, conv.project_id, conv.branch);
  if (!b) throw conflict(`Branch "${conv.branch}" is closed`, 'branch_closed');
  return b;
}

type LoadedConversation =
  | { conv: ConversationRow & { project_id: string }; project: ProjectRow; role: EffectiveRole; nexus: false }
  | { conv: ConversationRow; project: null; role: 'owner'; nexus: true };

/** Project conversations: project permission. Nexus conversations: private to their creator (others get 404). */
export function loadConversation(ctx: Ctx, u: UserRow, id: string, min: 'viewer' | 'editor' | 'owner'): LoadedConversation {
  const conv = ctx.db.prepare(`SELECT * FROM conversations WHERE id = ?`).get(id) as ConversationRow | undefined;
  if (!conv) throw notFound('Conversation not found');
  if (conv.scope === 'nexus' || conv.project_id == null) {
    if (conv.created_by !== u.id) throw notFound('Conversation not found');
    return { conv, project: null, role: 'owner', nexus: true };
  }
  const { project, role } = requireProject(ctx.db, u, conv.project_id, 'viewer');
  if (!hasRole(role, min)) throw forbidden(`Requires ${min} permission on this project`);
  return { conv: conv as ConversationRow & { project_id: string }, project, role, nexus: false };
}

/** Access to a run: project permission, or ownership of a Nexus run's conversation. */
export function runAccess(ctx: Ctx, u: UserRow, run: RunRow, min: 'viewer' | 'editor'): { project: ProjectRow | null; role: EffectiveRole } {
  if (run.project_id == null) {
    const conv = ctx.db.prepare(`SELECT created_by FROM conversations WHERE id = ?`).get(run.conversation_id) as { created_by: string | null } | undefined;
    if (conv?.created_by === u.id || run.user_id === u.id) return { project: null, role: 'owner' };
    if (u.role === 'admin' && min === 'editor') return { project: null, role: 'admin' }; // admins may abort any run
    throw notFound('Run not found');
  }
  const { project, role } = requireProject(ctx.db, u, run.project_id, 'viewer');
  if (min === 'editor' && !hasRole(role, 'editor') && run.user_id !== u.id) throw forbidden('Requires editor permission');
  return { project, role };
}


/** Start a run in a project conversation (prompt endpoint + Nexus handoffs). */
export async function startProjectPrompt(
  ctx: Ctx, req: FastifyRequest, u: UserRow, conv: ConversationRow & { project_id: string }, project: ProjectRow, body: PromptBody,
) {
  const { db, cfg, settings } = ctx;
  if (!body.text.trim() && !body.attachments.length) throw badRequest('Prompt is empty', 'empty_prompt');
  if (project.archived) throw conflict('Project is archived', 'archived');
  const branch = convBranch(ctx, conv);
  const s = settings.get();
  const model = body.model ?? conv.model ?? s.defaultModel;
  const mode: Mode = body.mode ?? conv.mode ?? 'auto';

  // ---- limits ----
  assertRunAllowed(ctx, u, conv, model, mode);

  // ---- agents ----
  const agents = effectiveAgents(db, project.id);
  let leadAgent = body.agent === undefined ? conv.agent_slug : body.agent;
  if (body.agent && !agents.has(body.agent)) throw badRequest(`Unknown or disabled agent "${body.agent}"`, 'unknown_agent');
  if (leadAgent && !agents.has(leadAgent)) leadAgent = null; // agent was disabled/deleted since

  // ---- attachments ----
  const uploads: UploadRow[] = [];
  for (const id of body.attachments) {
    const up = db.prepare(`SELECT * FROM uploads WHERE id = ?`).get(id) as UploadRow | undefined;
    if (!up) throw badRequest(`Unknown attachment ${id}`, 'unknown_attachment');
    const mine = up.user_id === u.id || u.role === 'admin';
    const sameProject = up.project_id === project.id;
    if (!mine && !(sameProject && projectRole(db, u, project.id))) throw forbidden('Attachment not accessible');
    uploads.push(up);
  }
  const attachmentPaths = uploads.map(
    (up) => `${cfg.claudeboxUploadsDir}/${up.id}/${path.basename(up.path)}`,
  );

  // ---- persist ----
  const t = now();
  const runId = crypto.randomUUID();
  const userMsgId = crypto.randomUUID();
  const asstMsgId = crypto.randomUUID();
  const isFirst = !db.prepare(`SELECT 1 FROM messages WHERE conversation_id = ? LIMIT 1`).get(conv.id);
  const title = isFirst && (conv.title === DEFAULT_TITLE || !conv.title) ? autoTitle(body.text) : null;
  db.transaction(() => {
    for (const up of uploads) if (!up.project_id) db.prepare(`UPDATE uploads SET project_id = ? WHERE id = ?`).run(project.id, up.id);
    db.prepare(
      `INSERT INTO runs(id, conversation_id, project_id, user_id, status, model, mode, thinking, started_at, ip, branch) VALUES (?,?,?,?, 'queued', ?,?,?,?,?,?)`,
    ).run(runId, conv.id, project.id, u.id, model, mode, body.thinking, t, req.clientIp, branch?.name ?? null);
    db.prepare(
      `INSERT INTO messages(id, conversation_id, role, content, attachments, run_id, user_id, created_at) VALUES (?,?, 'user', ?,?,?,?,?)`,
    ).run(userMsgId, conv.id, body.text, JSON.stringify(uploads.map((x) => x.id)), runId, u.id, t);
    db.prepare(
      `INSERT INTO messages(id, conversation_id, role, content, attachments, run_id, user_id, created_at) VALUES (?,?, 'assistant', '', '[]', ?, NULL, ?)`,
    ).run(asstMsgId, conv.id, runId, t + 1);
    db.prepare(`UPDATE conversations SET model = ?, mode = ?, updated_at = ?, title = COALESCE(?, title), agent_slug = ? WHERE id = ?`).run(
      model, mode, t, title, body.agent === undefined ? conv.agent_slug : body.agent, conv.id,
    );
  })();
  ctx.audit(req, 'prompt', runId, { conversationId: conv.id, projectId: project.id, model, mode, chars: body.text.length });

  const prompt = body.text.trim() || 'Please look at the attached file(s).';
  const authToken = settings.getAuthToken();
  if (mode !== 'ask' && mode !== 'plan') await preRunCheckpoint(ctx, project as ProjectRow, branch);
  ctx.runs.start({
    runId,
    conversationId: conv.id,
    projectId: project.id,
    userId: u.id,
    assistantMessageId: asstMsgId,
    branch: branch?.name ?? null,
    body: {
      runId,
      prompt,
      projectSlug: project.slug,
      ...(branch ? { worktree: branch.dir } : {}),
      sessionId: conv.claude_session_id,
      model,
      mode,
      thinking: body.thinking,
      attachments: attachmentPaths,
      appendSystemPrompt: buildSystemPrompt(project as ProjectRow, cfg, [...agents.values()].map((a) => ({ slug: a.slug, description: a.description })), branch),
      maxTurns: s.maxTurns,
      previewPort: branch ? branch.preview_port : project.preview_port,
      ...(authToken ? { authToken } : {}),
      ...sandboxBody(project as ProjectRow),
      ...(s.autoCompactTokens ? { autocompactTokens: s.autoCompactTokens } : {}),
      ...(agents.size ? { agents: cliAgents(agents) } : {}),
      ...(leadAgent ? { agent: leadAgent } : {}),
    },
  });
  return {
    runId,
    messageId: userMsgId,
    assistantMessageId: asstMsgId,
    conversation: conversationDTO(db.prepare(`SELECT * FROM conversations WHERE id = ?`).get(conv.id) as ConversationRow),
    attachments: loadAttachments(db, uploads.map((x) => x.id)),
  };
}

export default (ctx: Ctx): FastifyPluginAsync =>
  async (app) => {
    const { db, cfg, settings } = ctx;

    app.get('/api/projects/:id/conversations', async (req) => {
      const u = requireUser(req);
      const { project } = requireProject(db, u, (req.params as { id: string }).id, 'viewer');
      const q = req.query as { branch?: string; all?: string };
      const rows = (q.all === '1'
        ? db.prepare(`SELECT * FROM conversations WHERE project_id = ? ORDER BY updated_at DESC`).all(project.id)
        : db.prepare(`SELECT * FROM conversations WHERE project_id = ? AND branch IS ? ORDER BY updated_at DESC`)
          .all(project.id, branchParam(db, project, q.branch)?.name ?? null)) as ConversationRow[];
      return rows.map(conversationDTO);
    });

    app.post('/api/projects/:id/conversations', async (req, reply) => {
      const u = requireUser(req);
      const { project } = requireProject(db, u, (req.params as { id: string }).id, 'editor');
      const body = createSchema.parse(req.body ?? {});
      const branch = branchParam(db, project, body.branch ?? (req.query as { branch?: string }).branch);
      checkTopic(ctx, project.id, body.topicId);
      const s = settings.get();
      const t = now();
      const id = crypto.randomUUID();
      db.prepare(
        `INSERT INTO conversations(id, project_id, title, model, mode, created_by, created_at, updated_at, branch, topic_id) VALUES (?,?,?,?,?,?,?,?,?,?)`,
      ).run(id, project.id, body.title || DEFAULT_TITLE, body.model ?? s.defaultModel, body.mode ?? 'auto', u.id, t, t, branch?.name ?? null, body.topicId ?? null);
      reply.code(201);
      return conversationDTO(db.prepare(`SELECT * FROM conversations WHERE id = ?`).get(id) as ConversationRow);
    });

    app.get('/api/conversations/:id', async (req) => {
      const u = requireUser(req);
      const { conv } = loadConversation(ctx, u, (req.params as { id: string }).id, 'viewer');
      return conversationDTO(conv);
    });

    app.patch('/api/conversations/:id', async (req) => {
      const u = requireUser(req);
      const { conv, nexus } = loadConversation(ctx, u, (req.params as { id: string }).id, 'editor');
      const body = patchSchema.parse(req.body ?? {});
      if (nexus && (body.agentSlug || body.topicId)) throw badRequest('Nexus conversations have no agents or topics', 'nexus_unsupported');
      if (body.agentSlug && conv.project_id && !effectiveAgents(db, conv.project_id).has(body.agentSlug))
        throw badRequest(`Unknown or disabled agent "${body.agentSlug}"`, 'unknown_agent');
      if (conv.project_id) checkTopic(ctx, conv.project_id, body.topicId);
      if (body.topicId !== undefined) db.prepare(`UPDATE conversations SET topic_id = ? WHERE id = ?`).run(body.topicId, conv.id);
      db.prepare(
        `UPDATE conversations SET title = COALESCE(?, title), model = COALESCE(?, model), mode = COALESCE(?, mode),
           agent_slug = CASE WHEN ? THEN ? ELSE agent_slug END, updated_at = ? WHERE id = ?`,
      ).run(body.title ?? null, body.model ?? null, body.mode ?? null, body.agentSlug !== undefined ? 1 : 0, body.agentSlug ?? null, now(), conv.id);
      return conversationDTO(db.prepare(`SELECT * FROM conversations WHERE id = ?`).get(conv.id) as ConversationRow);
    });

    app.delete('/api/conversations/:id', async (req) => {
      const u = requireUser(req);
      const { conv, role } = loadConversation(ctx, u, (req.params as { id: string }).id, 'editor');
      if (role !== 'owner' && !hasRole(role, 'owner') && conv.created_by !== u.id) throw forbidden('Only the creator or a project owner can delete a conversation');
      const activeRun = ctx.runs.activeForConversation(conv.id);
      if (activeRun) await ctx.runs.abort(activeRun);
      ctx.runs.flushAll();
      db.prepare(`DELETE FROM conversations WHERE id = ?`).run(conv.id);
      ctx.audit(req, 'conversation_delete', conv.id, { title: conv.title, projectId: conv.project_id });
      return { ok: true };
    });

    app.get('/api/conversations/:id/messages', async (req) => {
      const u = requireUser(req);
      const { conv } = loadConversation(ctx, u, (req.params as { id: string }).id, 'viewer');
      const q = req.query as { events?: string };
      const rows = db.prepare(`SELECT * FROM messages WHERE conversation_id = ? ORDER BY created_at, rowid`).all(conv.id) as MessageRow[];
      return messagesDTO(db, rows, (runId) => ctx.runs.replay(runId, 0), q.events !== '0');
    });

    app.post(
      '/api/conversations/:id/prompt',
      { config: { rateLimit: { max: 30, timeWindow: '1 minute', keyGenerator: (req) => req.user?.id ?? req.clientIp } } },
      async (req) => {
        const u = requireUser(req);
        const l = loadConversation(ctx, u, (req.params as { id: string }).id, 'editor');
        const body = promptSchema.parse(req.body);
        if (!body.text.trim() && !body.attachments.length) throw badRequest('Prompt is empty', 'empty_prompt');
        if (l.nexus) return startNexusPrompt(ctx, req, u, l.conv, body);
        return startProjectPrompt(ctx, req, u, l.conv, l.project, body);
      },
    );

    // Manual compaction: summarize the Claude session to free context (`/compact [instructions]`).
    app.post(
      '/api/conversations/:id/compact',
      { config: { rateLimit: { max: 10, timeWindow: '1 minute', keyGenerator: (req) => req.user?.id ?? req.clientIp } } },
      async (req) => {
        const u = requireUser(req);
        const l = loadConversation(ctx, u, (req.params as { id: string }).id, 'editor');
        const body = compactSchema.parse(req.body ?? {});
        if (l.nexus) return startNexusCompact(ctx, req, u, l.conv, body.instructions);
        const { conv, project } = l;
        if (project.archived) throw conflict('Project is archived', 'archived');
        if (!conv.claude_session_id) throw conflict('Nothing to compact yet — this conversation has no Claude session.', 'no_session');
        const branch = convBranch(ctx, conv);
        const s = settings.get();
        const model = conv.model ?? s.defaultModel;
        const mode: Mode = conv.mode ?? 'auto';
        assertRunAllowed(ctx, u, conv, model, mode);

        const instructions = body.instructions.replace(/\s+/g, ' ').trim();
        const prompt = `/compact${instructions ? ` ${instructions}` : ''}`;
        const t = now();
        const runId = crypto.randomUUID();
        const userMsgId = crypto.randomUUID();
        const asstMsgId = crypto.randomUUID();
        db.transaction(() => {
          db.prepare(
            `INSERT INTO runs(id, conversation_id, project_id, user_id, status, model, mode, thinking, started_at, ip, branch) VALUES (?,?,?,?, 'queued', ?,?, 'off', ?,?,?)`,
          ).run(runId, conv.id, project.id, u.id, model, mode, t, req.clientIp, branch?.name ?? null);
          db.prepare(
            `INSERT INTO messages(id, conversation_id, role, content, attachments, run_id, user_id, created_at, kind) VALUES (?,?, 'user', ?, '[]', ?,?,?, 'compact')`,
          ).run(userMsgId, conv.id, prompt, runId, u.id, t);
          db.prepare(
            `INSERT INTO messages(id, conversation_id, role, content, attachments, run_id, user_id, created_at, kind) VALUES (?,?, 'assistant', '', '[]', ?, NULL, ?, 'compact')`,
          ).run(asstMsgId, conv.id, runId, t + 1);
          db.prepare(`UPDATE conversations SET updated_at = ? WHERE id = ?`).run(t, conv.id);
        })();
        ctx.audit(req, 'compact', runId, { conversationId: conv.id, projectId: project.id, model, chars: instructions.length });
        const authToken = settings.getAuthToken();
        ctx.runs.start({
          runId,
          conversationId: conv.id,
          projectId: project.id,
          userId: u.id,
          assistantMessageId: asstMsgId,
          kind: 'compact',
          branch: branch?.name ?? null,
          body: {
            runId,
            prompt,
            projectSlug: project.slug,
            ...(branch ? { worktree: branch.dir } : {}),
            sessionId: conv.claude_session_id,
            model,
            mode,
            thinking: 'off',
            attachments: [],
            appendSystemPrompt: '',
            maxTurns: s.maxTurns,
            previewPort: branch ? branch.preview_port : project.preview_port,
            ...(authToken ? { authToken } : {}),
            ...sandboxBody(project as ProjectRow),
          },
        });
        return {
          runId,
          messageId: userMsgId,
          assistantMessageId: asstMsgId,
          conversation: conversationDTO(db.prepare(`SELECT * FROM conversations WHERE id = ?`).get(conv.id) as ConversationRow),
        };
      },
    );

    app.get('/api/runs/:id', async (req) => {
      const u = requireUser(req);
      const run = db.prepare(`SELECT * FROM runs WHERE id = ?`).get((req.params as { id: string }).id) as RunRow | undefined;
      if (!run) throw notFound('Run not found');
      runAccess(ctx, u, run, 'viewer');
      return { ...runDTO(run), conversationId: run.conversation_id, projectId: run.project_id };
    });

    app.post('/api/runs/:id/abort', async (req) => {
      const u = requireUser(req);
      const run = db.prepare(`SELECT * FROM runs WHERE id = ?`).get((req.params as { id: string }).id) as RunRow | undefined;
      if (!run) throw notFound('Run not found');
      runAccess(ctx, u, run, 'editor');
      const ok = await ctx.runs.abort(run.id);
      ctx.audit(req, 'run_abort', run.id);
      return { ok };
    });
  };

// Nexus Chat routes: user-owned conversations that work across every project the user may edit.
import type { FastifyPluginAsync, FastifyRequest } from 'fastify';
import crypto from 'node:crypto';
import path from 'node:path';
import { z } from 'zod';
import { requireProject, requireUser, type ProjectRow, type UserRow } from '../auth.js';
import type { Ctx } from '../ctx.js';
import { now, parseJson } from '../db.js';
import { conversationDTO, loadAttachments, type ConversationRow, type RunRow, type UploadRow } from '../dto.js';
import { activeRunCount, ensureGit, getBranch, gitError, preRunCheckpoint } from '../lib/branches.js';
import { badRequest, conflict, forbidden, notFound } from '../lib/errors.js';
import {
  buildNexusIndex, buildNexusSystemPrompt, nexusRunSpec, nexusScope, nexusUid, resolveFocus, techHint, type Handoff, type NexusScope,
} from '../lib/nexus.js';
import type { NexusRunScope } from '../runs.js';
import type { Mode, NexusHandoff } from '../shared/protocol.js';
import { assertRunAllowed, autoTitle, DEFAULT_TITLE, runAccess, startProjectPrompt, type PromptBody } from './conversations.js';

const MODES = ['auto', 'edit', 'plan', 'ask'] as const;
const modelSchema = z.string().trim().min(1).max(100).regex(/^[A-Za-z0-9._:\-[\]]+$/, 'invalid model id');
const createSchema = z.object({ title: z.string().trim().max(200).optional(), model: modelSchema.optional(), mode: z.enum(MODES).optional() });
const handoffSchema = z.object({
  model: modelSchema.optional(),
  mode: z.enum(MODES).optional(),
  thinking: z.enum(['off', 'normal', 'max']).optional(),
});

/** Cost guardrail: Nexus conversations default to Sonnet (if enabled), whatever the workspace default is. */
function defaultNexusModel(ctx: Ctx): string {
  const s = ctx.settings.get();
  return s.models.some((m) => m.id === 'sonnet') ? 'sonnet' : s.defaultModel;
}

/** Run `fn` over items with bounded concurrency. */
async function pool<T>(items: T[], n: number, fn: (x: T) => Promise<void>) {
  const q = [...items];
  await Promise.all(Array.from({ length: Math.min(n, q.length) }, async () => {
    for (let x = q.shift(); x !== undefined; x = q.shift()) await fn(x);
  }));
}

export function scopeDTO(ctx: Ctx, scope: NexusScope) {
  return {
    projects: scope.projects.map((x) => ({
      id: x.project.id,
      slug: x.project.slug,
      name: x.project.name,
      color: x.project.color,
      icon: x.project.icon,
      description: x.project.description,
      parentId: x.project.parent_id,
      branches: x.branches.map((b) => b.name),
      busy: x.busy,
      tech: techHint(path.join(ctx.cfg.projectsDir, x.project.slug)),
      lastActiveAt: x.project.last_active_at ? new Date(x.project.last_active_at).toISOString() : null,
    })),
    viewOnly: scope.viewOnly,
  };
}

/** Prompt in a Nexus conversation: recompute scope, sandbox spec, index; pre-run checkpoints; start the run. */
export async function startNexusPrompt(ctx: Ctx, req: FastifyRequest, u: UserRow, conv: ConversationRow, body: PromptBody) {
  const { db, cfg, settings } = ctx;
  const s = settings.get();
  const model = body.model ?? conv.model ?? defaultNexusModel(ctx);
  const mode: Mode = body.mode ?? conv.mode ?? 'auto';
  assertRunAllowed(ctx, u, conv, model, mode);

  // ---- scope (authoritative, recomputed on every run) ----
  const scope = nexusScope(db, u);
  const focus = resolveFocus(scope, body.projects);
  if (focus.errors.length) throw badRequest(`Not in your Nexus scope (or no edit access): ${focus.errors.join(', ')}`, 'unknown_focus');
  const uid = nexusUid(db, u.id);
  const spec = nexusRunSpec(cfg, uid, scope, focus.items);

  // ---- attachments (own uploads only) ----
  const uploads: UploadRow[] = [];
  for (const id of body.attachments) {
    const up = db.prepare(`SELECT * FROM uploads WHERE id = ?`).get(id) as UploadRow | undefined;
    if (!up) throw badRequest(`Unknown attachment ${id}`, 'unknown_attachment');
    if (up.user_id !== u.id && u.role !== 'admin') throw forbidden('Attachment not accessible');
    uploads.push(up);
  }
  const attachmentPaths = uploads.map((up) => `${cfg.claudeboxUploadsDir}/${up.id}/${path.basename(up.path)}`);

  const runScope: NexusRunScope = {
    projects: [
      ...scope.projects.map((x) => ({ id: x.project.id, slug: x.project.slug, branch: null, worktree: null })),
      ...focus.items.filter((f) => f.branch).map((f) => ({ id: f.sp.project.id, slug: f.sp.project.slug, branch: f.branch!.name, worktree: f.branch!.dir })),
    ],
    focus: focus.items.map((f) => f.sp.project.slug + (f.branch ? `@${f.branch.name}` : '')),
  };

  // ---- persist ----
  const t = now();
  const runId = crypto.randomUUID();
  const userMsgId = crypto.randomUUID();
  const asstMsgId = crypto.randomUUID();
  const isFirst = !db.prepare(`SELECT 1 FROM messages WHERE conversation_id = ? LIMIT 1`).get(conv.id);
  const title = isFirst && (conv.title === DEFAULT_TITLE || !conv.title) ? autoTitle(body.text) : null;
  db.transaction(() => {
    db.prepare(
      `INSERT INTO runs(id, conversation_id, project_id, user_id, status, model, mode, thinking, started_at, ip, branch, nexus_scope)
       VALUES (?,?, NULL, ?, 'queued', ?,?,?,?,?, NULL, ?)`,
    ).run(runId, conv.id, u.id, model, mode, body.thinking, t, req.clientIp, JSON.stringify(runScope));
    db.prepare(
      `INSERT INTO messages(id, conversation_id, role, content, attachments, run_id, user_id, created_at) VALUES (?,?, 'user', ?,?,?,?,?)`,
    ).run(userMsgId, conv.id, body.text, JSON.stringify(uploads.map((x) => x.id)), runId, u.id, t);
    db.prepare(
      `INSERT INTO messages(id, conversation_id, role, content, attachments, run_id, user_id, created_at) VALUES (?,?, 'assistant', '', '[]', ?, NULL, ?)`,
    ).run(asstMsgId, conv.id, runId, t + 1);
    db.prepare(`UPDATE conversations SET model = ?, mode = ?, updated_at = ?, title = COALESCE(?, title) WHERE id = ?`).run(model, mode, t, title, conv.id);
  })();
  ctx.audit(req, 'nexus_prompt', runId, {
    conversationId: conv.id, model, mode, chars: body.text.length, projects: scope.projects.length, focus: runScope.focus, uid,
  });

  // Focused checkouts: pending edits are committed first ("nxeon: edits before run"), so the run's checkpoint holds only
  // its own changes. Other checkouts are never committed up front: we only note which ones are already dirty (read-only
  // `git status`); after the run those are checkpointed only if the run demonstrably touched them.
  if (mode !== 'ask' && mode !== 'plan') {
    const focusKeys = new Set(focus.items.map((f) => `${f.sp.project.id}|${f.branch?.name ?? ''}`));
    const dirty: string[] = [];
    const targets = runScope.projects.filter((x) => !activeRunCount(db, x.id, x.branch));
    await pool(targets, 4, async (x) => {
      const p = scope.projects.find((sp) => sp.project.id === x.id)?.project;
      if (!p) return;
      if (focusKeys.has(`${x.id}|${x.branch ?? ''}`)) {
        const b = x.branch ? getBranch(db, p.id, x.branch) : null;
        await preRunCheckpoint(ctx, p, b);
        return;
      }
      try {
        await ensureGit(ctx, p);
        const st = await ctx.cb.git<{ mainDirty?: boolean }>('status', { projectSlug: p.slug, branches: [] }, 8000);
        if (st.mainDirty) dirty.push(p.id);
      } catch {
        dirty.push(p.id); // unknown → treat as dirty (never sweep it into this run's checkpoint unless touched)
      }
    });
    runScope.dirty = dirty;
    db.prepare(`UPDATE runs SET nexus_scope = ? WHERE id = ?`).run(JSON.stringify(runScope), runId);
  }

  const index = buildNexusIndex(scope, focus.items, { cfg });
  const authToken = settings.getAuthToken();
  ctx.runs.start({
    runId,
    conversationId: conv.id,
    projectId: null,
    userId: u.id,
    assistantMessageId: asstMsgId,
    nexus: runScope,
    body: {
      runId,
      prompt: body.text.trim() || 'Please look at the attached file(s).',
      projectSlug: 'nexus',
      sessionId: conv.claude_session_id,
      model,
      mode,
      thinking: body.thinking,
      attachments: attachmentPaths,
      appendSystemPrompt: buildNexusSystemPrompt(index, spec.cwd, scope.viewOnly),
      maxTurns: s.maxTurns,
      ...(authToken ? { authToken } : {}),
      sandbox: spec.sandbox,
      cwd: spec.cwd,
      addDirs: spec.addDirs,
      ...(s.autoCompactTokens ? { autocompactTokens: s.autoCompactTokens } : {}),
    },
  });
  return {
    runId,
    messageId: userMsgId,
    assistantMessageId: asstMsgId,
    conversation: conversationDTO(db.prepare(`SELECT * FROM conversations WHERE id = ?`).get(conv.id) as ConversationRow),
    attachments: loadAttachments(db, uploads.map((x) => x.id)),
    scope: { projects: scope.projects.length, focus: runScope.focus },
  };
}

export async function startNexusCompact(ctx: Ctx, req: FastifyRequest, u: UserRow, conv: ConversationRow, instructions: string) {
  const { db, cfg, settings } = ctx;
  if (!conv.claude_session_id) throw conflict('Nothing to compact yet — this conversation has no Claude session.', 'no_session');
  const s = settings.get();
  const model = conv.model ?? defaultNexusModel(ctx);
  const mode: Mode = conv.mode ?? 'auto';
  assertRunAllowed(ctx, u, conv, model, mode);
  const scope = nexusScope(db, u);
  const uid = nexusUid(db, u.id);
  const spec = nexusRunSpec(cfg, uid, scope, []);
  const instr = instructions.replace(/\s+/g, ' ').trim();
  const prompt = `/compact${instr ? ` ${instr}` : ''}`;
  const t = now();
  const runId = crypto.randomUUID();
  const userMsgId = crypto.randomUUID();
  const asstMsgId = crypto.randomUUID();
  const runScope: NexusRunScope = { projects: [], focus: [] };
  db.transaction(() => {
    db.prepare(
      `INSERT INTO runs(id, conversation_id, project_id, user_id, status, model, mode, thinking, started_at, ip, nexus_scope) VALUES (?,?, NULL, ?, 'queued', ?,?, 'off', ?,?,?)`,
    ).run(runId, conv.id, u.id, model, mode, t, req.clientIp, JSON.stringify(runScope));
    db.prepare(
      `INSERT INTO messages(id, conversation_id, role, content, attachments, run_id, user_id, created_at, kind) VALUES (?,?, 'user', ?, '[]', ?,?,?, 'compact')`,
    ).run(userMsgId, conv.id, prompt, runId, u.id, t);
    db.prepare(
      `INSERT INTO messages(id, conversation_id, role, content, attachments, run_id, user_id, created_at, kind) VALUES (?,?, 'assistant', '', '[]', ?, NULL, ?, 'compact')`,
    ).run(asstMsgId, conv.id, runId, t + 1);
    db.prepare(`UPDATE conversations SET updated_at = ? WHERE id = ?`).run(t, conv.id);
  })();
  ctx.audit(req, 'compact', runId, { conversationId: conv.id, nexus: true, model, chars: instr.length });
  const authToken = settings.getAuthToken();
  ctx.runs.start({
    runId, conversationId: conv.id, projectId: null, userId: u.id, assistantMessageId: asstMsgId, kind: 'compact', nexus: runScope,
    body: {
      runId, prompt, projectSlug: 'nexus', sessionId: conv.claude_session_id, model, mode, thinking: 'off', attachments: [],
      appendSystemPrompt: '', maxTurns: s.maxTurns,
      ...(authToken ? { authToken } : {}), sandbox: spec.sandbox, cwd: spec.cwd, addDirs: spec.addDirs,
    },
  });
  return {
    runId, messageId: userMsgId, assistantMessageId: asstMsgId,
    conversation: conversationDTO(db.prepare(`SELECT * FROM conversations WHERE id = ?`).get(conv.id) as ConversationRow),
  };
}

/** Load a Nexus run the user owns (404 otherwise). */
function loadNexusRun(ctx: Ctx, u: UserRow, runId: string): RunRow {
  const run = ctx.db.prepare(`SELECT * FROM runs WHERE id = ?`).get(runId) as RunRow | undefined;
  if (!run || run.project_id != null) throw notFound('Run not found');
  runAccess(ctx, u, run, 'viewer');
  const owner = ctx.db.prepare(`SELECT created_by FROM conversations WHERE id = ?`).get(run.conversation_id) as { created_by: string } | undefined;
  if (owner?.created_by !== u.id) throw notFound('Run not found');
  return run;
}

/**
 * "Undo this run" for a Nexus run: `git revert` its checkpoint in every project it changed (or only `projectId`).
 * Each project needs editor permission now; per-project results (conflicts abort that project's revert only).
 */
export async function undoNexusRun(ctx: Ctx, req: FastifyRequest, u: UserRow, run: RunRow, projectId?: string) {
  const { db } = ctx;
  const rows = db
    .prepare(`SELECT * FROM nexus_run_commits WHERE run_id = ? AND undo_sha IS NULL ${projectId ? 'AND project_id = ?' : ''} ORDER BY id`)
    .all(...(projectId ? [run.id, projectId] : [run.id])) as { id: number; project_id: string; branch: string | null; sha: string }[];
  if (!rows.length) throw conflict('Nothing to undo (no unreverted checkpoints)', 'no_checkpoint');
  const results: { projectId: string; slug: string; branch: string | null; ok: boolean; sha?: string | null; conflicts?: string[]; error?: string }[] = [];
  for (const c of rows) {
    let slug = '?';
    try {
      const { project } = requireProject(db, u, c.project_id, 'editor');
      slug = project.slug;
      const b = c.branch ? getBranch(db, project.id, c.branch) : null;
      if (c.branch && !b) throw conflict(`Branch "${c.branch}" is closed`, 'branch_closed');
      if (activeRunCount(db, project.id, c.branch)) throw conflict('A run is active in this project — wait for it to finish', 'run_in_progress');
      const main = await ensureGit(ctx, project);
      const r = await ctx.cb.git<{ ok: boolean; sha?: string | null; conflicts?: string[] }>('revert', {
        projectSlug: project.slug, ...(b ? { worktree: b.dir } : {}), sha: c.sha, expectBranch: b ? b.name : main,
      });
      if (!r.ok) {
        results.push({ projectId: project.id, slug, branch: c.branch, ok: false, conflicts: r.conflicts ?? [] });
        continue;
      }
      db.prepare(`UPDATE nexus_run_commits SET undo_sha = ? WHERE id = ?`).run(r.sha ?? 'empty', c.id);
      ctx.hub.broadcastProject(project.id, { t: 'project_changed', projectId: project.id, what: 'history', branch: c.branch });
      results.push({ projectId: project.id, slug, branch: c.branch, ok: true, sha: r.sha ?? null });
    } catch (err) {
      results.push({ projectId: c.project_id, slug, branch: c.branch, ok: false, error: gitError(err).message });
    }
  }
  ctx.audit(req, 'nexus_undo', run.id, { results: results.map((r) => ({ p: r.slug, ok: r.ok })) });
  return { ok: results.every((r) => r.ok), results };
}

