    try {
      const cleaned = models.map((m) => ({ id: m.id.trim(), label: m.label.trim() }));
      await saveSettings({ models: cleaned, defaultModel: cleaned.some((m) => m.id === def) ? def : cleaned[0].id, globalDailyTokenCap: capNum === null ? null : Math.round(capNum), autoCompactTokens: acNum });
