// Workspace store (one active workspace at a time; reset on project change).
import { create } from 'zustand';
import { api, ApiError } from '@/lib/api';
import { live } from '@/lib/ws';
import type {
  Agent, Attachment, Branch, BranchList, Conversation, DiffSummary, FileDiff, FileNode, History, Message, ModelInfo, PreviewStatus,
  Project, Run, StoredEvent, Topic, UsageSummary,
} from '@/lib/types';
import type { Mode, RunStatus, ServerMsg, Suggestion, ThinkingLevel } from '@/shared/protocol';
import { applyRunEvent, changedLines, emptyRun, replay, setStatus, type RunView, type SeqEvent } from './reducer';

// ---------- types ----------
export interface ChatItem {
  key: string;
  id?: string;
  role: 'user' | 'assistant';
  content: string;
  attachments: Attachment[];
  createdAt: string;
  userName?: string;
  runId?: string | null;
  run?: Run | null;
  suggestions?: Suggestion[];
  kind?: 'compact';
}

export interface PendingUpload {
  localId: string;
  file: File;
  name: string;
  size: number;
  mime: string;
  previewUrl?: string;
  progress: number;
  status: 'uploading' | 'done' | 'error';
  error?: string;
  result?: Attachment;
}

export interface CodeTab {
  path: string;
  content: string;      // current editor content
  saved: string;        // last known on-disk content
  loading: boolean;
  error?: string;
  binary?: boolean;
  tooLarge?: boolean;   // > server read limit: not editable
  externalContent?: string | null;  // pending external change while dirty
  deleted?: boolean;
  flashAt?: number;     // "updated by Claude" flash
  flashLines?: number[];
  saving?: boolean;
}

export type RightTab = 'preview' | 'code';
export type LeftTab = 'files' | 'chats';
export type MobileTab = 'chat' | 'files' | 'preview' | 'code';

export interface Prefs { model: string; mode: Mode; thinking: ThinkingLevel }
export interface PreviewPrefs { autoRefresh: boolean; hmr: boolean; device: 'mobile' | 'tablet' | 'full'; subPath: string }

export interface SendError { code: string; message: string; status: number; limit?: boolean }

export interface CompareState {
  branch: string;
  loading: boolean;
  error?: string;
  summary: DiffSummary | null;
  selected: string | null;
  file: FileDiff | null;
  fileLoading: boolean;
}
export interface MergeResult { ok: boolean; conflicts?: string[]; resolvePrompt?: string; closed?: boolean; into?: string }

interface State {
  project: Project | null;
  projectError: string | null;
  canEdit: boolean;
  connected: boolean;

  /** current branch (git worktree) — null = main checkout. Mirrors `?branch=` in the URL. */
  branch: string | null;
  branchList: BranchList | null;
  /** parent project (sub-project view) and sibling/child projects for the breadcrumb */
  family: { parent: Project | null; children: Project[]; siblings: Project[] };
  topics: Topic[];
  /** `?topic=` filter for the conversation list */
  topicFilter: string | null;
  collapsedTopics: Record<string, boolean>;
  history: History | null;
  historyLoading: boolean;
  compare: CompareState | null;
  /** prompt to send right after the next branch switch (conflict "Ask Claude to resolve") */
  pendingPrompt: string | null;

  conversations: Conversation[];
  convLoading: boolean;
  activeConvId: string | null;
  items: ChatItem[];
  itemsLoading: boolean;
  runs: Record<string, RunView>;
  liveSuggestions: Record<string, Suggestion[]>;

  models: ModelInfo[];
  prefs: Prefs;
  draft: { text: string; nonce: number };
  uploads: PendingUpload[];
  sending: boolean;
  sendError: SendError | null;
  usage: UsageSummary | null;

  /** global + project agents (subagents) */
  agents: Agent[];
  agentsOpen: boolean;
  /** lead agent chosen before the conversation exists (sent with the first prompt) */
  draftAgent: string | null;

  tree: FileNode[] | null;
  treeError: string | null;
  flashes: Record<string, number>;
