        if (!convId) {
          const title = text.trim().split('\n')[0].slice(0, 60) || 'New conversation';
          const conv = unwrap<Conversation>(await api.post<any>(`/projects/${project.id}/conversations`, { title, model: s.prefs.model, mode: s.prefs.mode, branch: s.branch, topicId: s.topicFilter }), 'conversation');
