test("/v2 requires bearer auth and validates input", async () => {
  assert.equal((await request("GET", "/v2/runs", undefined, {})).status, 401);
  assert.equal((await request("GET", "/v2/runs", undefined, { Authorization: "Bearer nope" })).status, 401);
  assert.equal((await request("POST", "/v2/run", { prompt: "x", projectSlug: "../etc" })).status, 400);
  assert.equal((await request("POST", "/v2/run", { prompt: "x", projectSlug: "Upper" })).status, 400);
  assert.equal((await request("POST", "/v2/run", { prompt: "x", projectSlug: "ok", mode: "yolo" })).status, 400);
  assert.equal((await request("POST", "/v2/run", { prompt: "x", projectSlug: "ok", attachments: ["/etc/passwd"] })).status, 400);
  assert.equal((await request("POST", "/v2/run", { prompt: "x", projectSlug: "ok", previewPort: 22 })).status, 400);
});

test("POST /v2/run streams normalized SSE events with flags/env applied", async () => {
  const attachment = path.join(TMP, "uploads", "u1", "a.png");
  const events = await sse("POST", "/v2/run", {
    runId: "run-basic",
    prompt: "build an app",
    projectSlug: "my-app",
    sessionId: "aaaaaaaa-bbbb-cccc-dddd-eeeeeeeeeeee",
    model: "sonnet",
    mode: "auto",
    thinking: "max",
    attachments: [attachment],
    appendSystemPrompt: "be nice",
    maxTurns: 7,
    previewPort: 4123,
    authToken: "sk-ant-api03-xyz",
  });
  const types = events.map((e) => e.type);
  assert.equal(types[0], "init");
  assert.equal(types[types.length - 1], "done");
  assert.deepEqual(events[events.length - 1].data, { exitCode: 0 });
  assert.deepEqual(events.map((e) => e.id), events.map((_, i) => i + 1));
  assert.ok(types.includes("result"));
  assert.equal(events.filter((e) => e.type === "text").map((e) => e.data.delta).join(""), "I'll set things up.Done! Server ready.");

  const rec = JSON.parse(fs.readFileSync(ARGS_FILE, "utf8"));
  const arg = (f) => rec.args[rec.args.indexOf(f) + 1];
  assert.equal(rec.cwd, path.join(TMP, "projects", "my-app"));
  assert.equal(arg("--model"), "sonnet");
  assert.equal(arg("--resume"), "aaaaaaaa-bbbb-cccc-dddd-eeeeeeeeeeee");
  assert.equal(arg("--permission-mode"), "bypassPermissions");
  assert.equal(arg("--max-turns"), "7");
  assert.equal(arg("--append-system-prompt"), "be nice");
  assert.equal(arg("--add-dir"), path.join(TMP, "uploads"));
  assert.ok(rec.prompt.endsWith(`[Attached file: ${attachment} — use Read tool]`));
  assert.equal(rec.env.MAX_THINKING_TOKENS, "32000");
  assert.equal(rec.env.ANTHROPIC_API_KEY, "sk-ant-api03-xyz");
  assert.equal(rec.env.CLAUDE_CODE_OAUTH_TOKEN, undefined);
  assert.equal(rec.env.CLAUDEBOX_API_KEY, undefined);
  assert.equal(rec.env.PORT, "4123");
  assert.equal(rec.env.BASE_PATH, "/preview/my-app/");

  // duplicate runId
  assert.equal((await request("POST", "/v2/run", { runId: "run-basic", prompt: "x", projectSlug: "my-app" })).status, 409);

  // replay after completion (inclusive fromSeq)
  const replay = await sse("GET", "/v2/run/run-basic/events?fromSeq=3");
  assert.equal(replay[0].id, 3);
  assert.deepEqual(replay.map((e) => e.type), types.slice(2));
  const info = await request("GET", "/v2/run/run-basic");
  assert.equal(info.json.status, "done");
  assert.equal(info.json.sessionId, "aaaaaaaa-bbbb-cccc-dddd-eeeeeeeeeeee");
});

test("OAuth authToken and thinking=off", async () => {
  await sse("POST", "/v2/run", { runId: "run-oauth", prompt: "hi", projectSlug: "p2", thinking: "off", authToken: "sk-ant-oat01-abc", mode: "edit" });
  const rec = JSON.parse(fs.readFileSync(ARGS_FILE, "utf8"));
  assert.equal(rec.env.CLAUDE_CODE_OAUTH_TOKEN, "sk-ant-oat01-abc");
  assert.equal(rec.env.ANTHROPIC_API_KEY, undefined);
  assert.equal(rec.env.MAX_THINKING_TOKENS, "0");
  assert.equal(rec.env.PORT, undefined);
  assert.equal(rec.args[rec.args.indexOf("--permission-mode") + 1], "acceptEdits");
});

test("POST /v2/run: agents (inline + temp file), lead agent, autocompact; compact run", async () => {
  const agents = { reviewer: { description: "Reviews code", prompt: "You review.", tools: ["Read"], model: "haiku" } };
  const bad = await request("POST", "/v2/run", { prompt: "x", projectSlug: "p4", agents, agent: "nope" });
  assert.equal(bad.status, 400);
  assert.equal((await request("POST", "/v2/run", { prompt: "x", projectSlug: "p4", autocompactTokens: 5 })).status, 400);
  const evs = await sse("POST", "/v2/run", { runId: "run-agents", prompt: "DELEGATE", projectSlug: "p4", agents, agent: "reviewer", autocompactTokens: 80000 });
  assert.equal(evs.at(-1).type, "done");
  let rec = JSON.parse(fs.readFileSync(ARGS_FILE, "utf8"));
  const arg = (f) => rec.args[rec.args.indexOf(f) + 1];
  assert.deepEqual(JSON.parse(arg("--agents")), agents);
  assert.equal(arg("--agent"), "reviewer");
  assert.equal(arg("--autocompact"), "100000");
  assert.ok(rec.args.includes("--forward-subagent-text"));
  // big agent set goes through a temp file which is removed afterwards
  const big = {};
  for (let i = 0; i < 20; i++) big[`a${i}`] = { description: "d", prompt: "p".repeat(3000) };
  await sse("POST", "/v2/run", { runId: "run-agents-big", prompt: "hi", projectSlug: "p4", agents: big });
  rec = JSON.parse(fs.readFileSync(ARGS_FILE, "utf8"));
  const file = arg("--agents");
  assert.ok(file.endsWith(".json") && !file.startsWith("{"), file);
  await new Promise((r) => setTimeout(r, 50));
  assert.equal(fs.existsSync(file), false);

  const c = await sse("POST", "/v2/run", { runId: "run-compact", prompt: "/compact", projectSlug: "p4", sessionId: "sess-1" });
  assert.deepEqual(c.map((e) => e.type), ["init", "compact", "usage", "result", "done"]);
});

