test("buildRunArgs: autocompact, agents, lead agent, forward-subagent-text", () => {
  const { autocompactPlan, validateAgents, buildChildEnv } = require("../lib/runs");
  assert.equal(autocompactPlan(0), null);
  assert.deepEqual(autocompactPlan(150000), { window: 163000, pct: null });
  assert.deepEqual(autocompactPlan(80000), { window: 100000, pct: 80 });
  assert.equal(buildChildEnv({}, { projectSlug: "p", runId: "r", autocompactTokens: 80000 }).CLAUDE_AUTOCOMPACT_PCT_OVERRIDE, "80");
  assert.equal(buildChildEnv({ CLAUDE_AUTOCOMPACT_PCT_OVERRIDE: "5" }, { projectSlug: "p", runId: "r", autocompactTokens: 150000 }).CLAUDE_AUTOCOMPACT_PCT_OVERRIDE, undefined);
  const agents = { reviewer: { description: "Reviews code", prompt: "You review.", tools: ["Read", "Grep"], model: "sonnet" } };
  assert.deepEqual(validateAgents(agents), { agents });
  assert.ok(validateAgents({ "Bad Name": agents.reviewer }).error);
  assert.ok(validateAgents({ x: { description: "d" } }).error);
  const f = { forwardSubagentText: true };
  const args = buildRunArgs({ prompt: "hi", mode: "edit", autocompactTokens: 80000, agents, agent: "reviewer" }, f, {});
  assert.equal(args[args.indexOf("--autocompact") + 1], "100000");
  assert.deepEqual(JSON.parse(args[args.indexOf("--agents") + 1]), agents);
  assert.equal(args[args.indexOf("--agent") + 1], "reviewer");
  assert.ok(args.includes("--forward-subagent-text"));
  assert.ok(args.includes("Agent"), "edit mode pre-approves the Agent tool when agents are passed");

