// Cost model for estimates, cold-resume decisions and runs that end without a reported cost.
// Numbers: docs/research/token-efficiency.md (API-equivalent prices; cache writes at the 1-hour TTL rate).
import type { AppSettings, ModelFamily, ModelPrice } from '../settings.js';
import type { Usage } from '../shared/protocol.js';

/** Fixed per-call overhead (tools + system prompt + our append), measured on Sonnet 5.5 (see docs). */
export const BASE_TOKENS = { lean: 9_000, full: 17_500 } as const;
/** Rough per-turn assumptions for the pre-send estimate. */
export const TYPICAL = { newInput: 800, output: 1_200, extraCalls: 2, perCallWrite: 600 } as const;
/** Free SQLite summary injected on a fresh restart (cap). */
export const SUMMARY_TOKENS = 2_500;

export function modelFamily(model: string | null | undefined): ModelFamily {
  const m = (model ?? '').toLowerCase();
  if (m.includes('opus')) return 'opus';
  if (m.includes('haiku')) return 'haiku';
  return 'sonnet';
}

export function priceFor(s: Pick<AppSettings, 'prices'>, model: string | null | undefined): ModelPrice {
  const fam = modelFamily(model);
  return s.prices?.[fam] ?? { input: 2, output: 10, cacheWrite: 4, cacheRead: 0.2 };
}

/** $ for a token usage (cache writes priced at the 1-hour rate — upper bound for subagents/5-min writes). */
export function usageCost(u: Usage, p: ModelPrice): number {
  const usd = (u.inputTokens * p.input + u.outputTokens * p.output + u.cacheWriteTokens * p.cacheWrite + u.cacheReadTokens * p.cacheRead) / 1e6;
  return Math.round(usd * 1e6) / 1e6;
}

export interface TurnEstimate {
  usd: number;
  warm: boolean;
  contextTokens: number;
  breakdown: { context: number; input: number; output: number; toolCalls: number };
}

/**
 * Expected cost of the next prompt: reading the context once (cache read when warm, 1h cache write when cold),
 * writing the new prompt, a typical reply, plus a couple of tool round-trips (none in ask mode).
 */
export function estimateTurn(o: { contextTokens: number; warm: boolean; price: ModelPrice; lean: boolean; mode?: string }): TurnEstimate {
  const p = o.price;
  const base = o.lean ? BASE_TOKENS.lean : BASE_TOKENS.full;
  const ctx = Math.max(o.contextTokens || 0, base);
  const context = (ctx * (o.warm ? p.cacheRead : p.cacheWrite)) / 1e6;
  const input = (TYPICAL.newInput * p.cacheWrite) / 1e6;
  const output = (TYPICAL.output * p.output) / 1e6;
  const calls = o.mode === 'ask' ? 0 : TYPICAL.extraCalls;
  const toolCalls = (calls * (ctx * p.cacheRead + TYPICAL.perCallWrite * p.cacheWrite)) / 1e6;
  const r = (n: number) => Math.round(n * 1e5) / 1e5;
  return {
    usd: r(context + input + output + toolCalls),
    warm: o.warm,
    contextTokens: o.contextTokens || 0,
    breakdown: { context: r(context), input: r(input), output: r(output), toolCalls: r(toolCalls) },
  };
}

/** First-call cost of resuming a cold conversation vs. starting a fresh session seeded with the free summary. */
export function coldResumeCosts(contextTokens: number, price: ModelPrice, lean: boolean) {
  const base = lean ? BASE_TOKENS.lean : BASE_TOKENS.full;
  const r = (n: number) => Math.round(n * 1e4) / 1e4;
  return {
    resumeCostUsd: r((Math.max(contextTokens, base) * price.cacheWrite) / 1e6),
    freshCostUsd: r(((base + SUMMARY_TOKENS) * price.cacheWrite) / 1e6),
  };
}

export interface CacheState {
  /** minutes since the conversation's last run activity (null = never ran) */
  idleMinutes: number | null;
  /** prompt cache still warm (same model, within the TTL window) */
  warm: boolean;
  /** resuming now would re-write a large cold context → ask the user */
  cold: boolean;
}

/** Cache warmth + the cold-resume decision for a conversation (pure). */
export function cacheState(
  o: { lastActivityAt: number | null; contextTokens: number | null; hasSession: boolean; convModel: string | null; model: string; now: number },
  s: Pick<AppSettings, 'coldResumeGuard' | 'coldResumeMinutes' | 'coldResumeMinTokens'>,
): CacheState {
  const idleMinutes = o.lastActivityAt ? Math.max(0, (o.now - o.lastActivityAt) / 60_000) : null;
  const withinTtl = idleMinutes != null && idleMinutes <= s.coldResumeMinutes;
  const sameModel = !o.convModel || modelFamily(o.convModel) === modelFamily(o.model) && o.convModel === o.model;
  const warm = o.hasSession && withinTtl && sameModel;
  const cold =
    !!s.coldResumeGuard && o.hasSession && idleMinutes != null && idleMinutes > s.coldResumeMinutes && (o.contextTokens ?? 0) > s.coldResumeMinTokens;
  return { idleMinutes: idleMinutes == null ? null : Math.round(idleMinutes), warm, cold };
}

/** Friendly message for runs stopped by a guardrail (null = not a limit stop). */
export function limitStop(code: unknown, o: { maxTurns?: number; maxBudgetUsd?: number }): { kind: 'budget' | 'turns'; message: string } | null {
  if (code === 'error_max_budget_usd')
    return { kind: 'budget', message: `Stopped: this run reached its cost limit${o.maxBudgetUsd ? ` ($${o.maxBudgetUsd.toFixed(2)})` : ''}. Send "continue" to resume where it stopped.` };
  if (code === 'error_max_turns')
    return { kind: 'turns', message: `Stopped: this run reached its step limit${o.maxTurns ? ` (${o.maxTurns} turns)` : ''}. Send "continue" to resume where it stopped.` };
  return null;
}

