// Free (no model call) conversation summary built from SQLite, used to start a fresh Claude session in the same
// conversation instead of resuming a cache-cold large context ("Continue fresh"). Capped at ~2.5k tokens.
import type { DB } from '../db.js';
import { parseJson } from '../db.js';

export const SUMMARY_MAX_CHARS = 9_000; // ≈ 2.3–2.5k tokens
const WRITE_TOOLS = new Set(['Write', 'Edit', 'MultiEdit', 'NotebookEdit']);

const clip = (s: string, n: number) => {
  const t = s.replace(/\s+/g, ' ').trim();
  return t.length > n ? t.slice(0, n - 1).trimEnd() + '…' : t;
};

/** Make a tool path readable: drop the claudebox projects prefix (and the project's own dir for project chats). */
export function relPath(p: string, projectsDir: string, slug: string | null): string {
  let r = p;
  const root = projectsDir.replace(/\/+$/, '') + '/';
  if (r.startsWith(root)) r = r.slice(root.length);
  if (r.startsWith('.branches/')) r = r.split('/').slice(3).join('/');
  else if (slug && r.startsWith(slug + '/')) r = r.slice(slug.length + 1);
  return r;
}

export interface SummaryInput {
  turns: { user: string; assistant: string; status?: string | null }[];
  files: string[];
  todos: { content: string; status: string }[];
}

/** Pure formatter (unit-tested): first turn + the most recent turns, files changed, open todos; hard char cap. */
export function formatSummary(inp: SummaryInput, maxChars = SUMMARY_MAX_CHARS): string {
  const turns = inp.turns.filter((t) => t.user.trim() || t.assistant.trim());
  if (!turns.length) return '';
  const recent = turns.slice(-5);
  const first = turns.length > recent.length ? turns[0] : null;
  const fmt = (t: SummaryInput['turns'][number], last: boolean) => {
    const a = t.assistant ? clip(t.assistant, last ? 900 : 450) : t.status && t.status !== 'done' ? `(run ${t.status})` : '(no reply)';
    return `- User: ${clip(t.user, 300)}\n  Assistant: ${a}`;
  };
  const out: string[] = [`${turns.length} earlier turn${turns.length === 1 ? '' : 's'} in this chat (older details are not available; re-read files when needed).`];
  if (first) out.push('First request:', fmt(first, false), `(… ${turns.length - recent.length - 1} turn(s) omitted …)`);
  out.push('Most recent turns:', ...recent.map((t, i) => fmt(t, i === recent.length - 1)));
  if (inp.files.length) out.push(`Files changed so far: ${inp.files.slice(-25).join(', ')}`);
  const open = inp.todos.filter((t) => t.status !== 'completed');
  if (open.length) out.push('Open todos:', ...open.slice(0, 10).map((t) => `- [${t.status === 'in_progress' ? '~' : ' '}] ${clip(t.content, 160)}`));
  let s = out.join('\n');
  if (s.length > maxChars) s = s.slice(0, maxChars - 1) + '…';
  return s;
}

/** Collect the summary inputs for a conversation from messages + run_events. */
export function summaryInput(db: DB, conversationId: string, projectsDir: string, slug: string | null): SummaryInput {
  const msgs = db
    .prepare(
      `SELECT m.role, m.content, m.run_id, r.status FROM messages m LEFT JOIN runs r ON r.id = m.run_id
       WHERE m.conversation_id = ? AND (m.kind IS NULL OR m.kind != 'compact') ORDER BY m.created_at, m.rowid`,
    )
    .all(conversationId) as { role: string; content: string; run_id: string | null; status: string | null }[];
  const turns: SummaryInput['turns'] = [];
  for (const m of msgs) {
    if (m.role === 'user') turns.push({ user: m.content || '', assistant: '', status: m.status });
    else if (turns.length) turns[turns.length - 1]!.assistant = m.content || '';
  }
  const evs = db
    .prepare(
      `SELECT e.type, e.data FROM run_events e JOIN runs r ON r.id = e.run_id
       WHERE r.conversation_id = ? AND e.type IN ('tool_use','todo') ORDER BY r.started_at, e.seq`,
    )
    .all(conversationId) as { type: string; data: string }[];
  const files: string[] = [];
  let todos: SummaryInput['todos'] = [];
  for (const e of evs) {
    const d = parseJson<Record<string, unknown>>(e.data, {});
    if (e.type === 'todo' && Array.isArray(d.todos)) todos = d.todos as SummaryInput['todos'];
    if (e.type === 'tool_use' && !d.parentId && typeof d.name === 'string' && WRITE_TOOLS.has(d.name)) {
      const fp = (d.input as { file_path?: unknown } | undefined)?.file_path;
      if (typeof fp === 'string' && fp) {
        const r = relPath(fp, projectsDir, slug);
        const i = files.indexOf(r);
        if (i >= 0) files.splice(i, 1);
        files.push(r);
      }
    }
  }
  return { turns, files, todos };
}

export function buildConversationSummary(db: DB, conversationId: string, projectsDir: string, slug: string | null): string {
  return formatSummary(summaryInput(db, conversationId, projectsDir, slug));
}

/** The block appended to the system prompt of a fresh session. */
export function summaryBlock(summary: string): string {
  return summary ? `\n\nConversation so far (summary — this chat was restarted in a fresh session to save tokens):\n${summary}` : '';
}

