export interface RunEfficiency {
  /** session to resume (null after a 'fresh' choice) */
  sessionId: string | null;
  /** appended to the system prompt (fresh restart summary) */
  appendSuffix: string;
  lean: boolean;
  effort?: 'low';
  maxBudgetUsd?: number;
  resumeChoice: 'resume' | 'fresh' | null;
  savedUsd: number | null;
}

/**
 * Per-run efficiency policy: lean flags, budget cap, effort for ask mode and the cold-resume guard
 * (throws 409 `cold_resume` with cost estimates unless the request carries `resumeChoice`).
 */
export function runEfficiency(
  ctx: Ctx, conv: ConversationRow, model: string, mode: Mode, resumeChoice: 'resume' | 'fresh' | undefined, slug: string | null,
): RunEfficiency {
  const s = ctx.settings.get();
  const lean = !!s.leanMode;
  const price = priceFor(s, model);
  const st = cacheState(
    { lastActivityAt: conv.last_activity_at ?? null, contextTokens: conv.context_tokens, hasSession: !!conv.claude_session_id, convModel: conv.model, model, now: now() },
    s,
  );
  let sessionId = conv.claude_session_id;
  let appendSuffix = '';
  let choice: RunEfficiency['resumeChoice'] = null;
  let savedUsd: number | null = null;
  if (st.cold) {
    const est = coldResumeCosts(conv.context_tokens ?? 0, price, lean);
    if (!resumeChoice) {
      const k = Math.round((conv.context_tokens ?? 0) / 1000);
      throw new HttpError(
        409, 'cold_resume',
        `This chat has been idle ${fmtIdle(st.idleMinutes ?? 0)} — resuming re-reads ~${k}k tokens (~$${est.resumeCostUsd.toFixed(2)}). Continue fresh with a summary (~$${est.freshCostUsd.toFixed(2)})?`,
        { idleMinutes: st.idleMinutes, contextTokens: conv.context_tokens ?? 0, model, ...est },
      );
    }
    choice = resumeChoice;
    if (resumeChoice === 'fresh') {
      sessionId = null;
      appendSuffix = summaryBlock(buildConversationSummary(ctx.db, conv.id, ctx.cfg.claudeboxProjectsDir, slug));
      savedUsd = Math.max(0, Math.round((est.resumeCostUsd - est.freshCostUsd) * 1e4) / 1e4);
    }
  }
  const budget = s.maxBudgetUsd?.[modelFamily(model)] ?? 0;
  return {
    sessionId, appendSuffix, lean,
    ...(lean && mode === 'ask' ? { effort: 'low' as const } : {}),
    ...(budget > 0 ? { maxBudgetUsd: budget } : {}),
    resumeChoice: choice, savedUsd,
  };
}

/** Pre-send estimate for the prompt box (`conv` null = a new chat). */
export function conversationEstimate(ctx: Ctx, conv: ConversationRow | null, model: string, mode: string) {
  const s = ctx.settings.get();
  const price = priceFor(s, model);
  const st = conv
    ? cacheState({ lastActivityAt: conv.last_activity_at ?? null, contextTokens: conv.context_tokens, hasSession: !!conv.claude_session_id, convModel: conv.model, model, now: now() }, s)
    : { idleMinutes: null, warm: true, cold: false }; // new chat: the shared base prompt is usually cached
  const ctxTokens = conv?.claude_session_id ? conv.context_tokens ?? 0 : 0;
  return {
    model,
    contextTokens: ctxTokens,
    idleMinutes: st.idleMinutes,
    warm: st.warm,
    estimate: estimateTurn({ contextTokens: ctxTokens, warm: st.warm, price, lean: !!s.leanMode, mode }),
    coldResume: st.cold ? { idleMinutes: st.idleMinutes, ...coldResumeCosts(ctxTokens, price, !!s.leanMode) } : null,
    newChatHintTokens: s.newChatHintTokens,
    cacheMinutes: s.coldResumeMinutes,
  };
}

