import { afterAll, beforeAll, describe, expect, it } from 'vitest';
import { cacheState, coldResumeCosts, estimateTurn, limitStop, modelFamily, priceFor, usageCost } from '../src/lib/cost.js';
import { formatSummary, relPath, SUMMARY_MAX_CHARS } from '../src/lib/summary.js';
import { DEFAULT_SETTINGS } from '../src/settings.js';
import { buildSystemPrompt } from '../src/runs.js';
import { api, createUser, login, makeEnv, type TestEnv } from './helpers.js';

const S = DEFAULT_SETTINGS;
const MIN = 60_000;

describe('efficiency: pure helpers', () => {
  it('settings defaults', () => {
    expect(S.leanMode).toBe(true);
    expect(S.coldResumeGuard).toBe(true);
    expect(S.maxTurns).toBe(30);
    expect(S.coldResumeMinutes).toBe(55);
    expect(S.coldResumeMinTokens).toBe(30_000);
    expect(S.maxBudgetUsd).toEqual({ opus: 2, sonnet: 1, haiku: 0.5 });
    expect(S.newChatHintTokens).toBe(60_000);
    expect(S.prices.sonnet).toEqual({ input: 2, output: 10, cacheWrite: 4, cacheRead: 0.2 });
    expect(S.prices.opus.output).toBe(20);
    expect(S.prices.haiku.input).toBe(1);
  });

  it('model family + usage cost (matches a measured Sonnet run)', () => {
    expect(modelFamily('opus')).toBe('opus');
    expect(modelFamily('claude-haiku-4-5')).toBe('haiku');
    expect(modelFamily('sonnet')).toBe('sonnet');
    expect(modelFamily('something-else')).toBe('sonnet');
    // measured: 2 in, 95 out, 10350 read, 7334 write → $0.0324 reported by the CLI
    expect(usageCost({ inputTokens: 2, outputTokens: 95, cacheReadTokens: 10350, cacheWriteTokens: 7334 }, priceFor(S, 'sonnet'))).toBeCloseTo(0.03236, 5);
  });

  it('turn estimate: warm vs cold, ask mode has no tool round-trips', () => {
    const p = priceFor(S, 'sonnet');
    const warm = estimateTurn({ contextTokens: 80_000, warm: true, price: p, lean: true });
    const cold = estimateTurn({ contextTokens: 80_000, warm: false, price: p, lean: true });
    expect(warm.breakdown.context).toBeCloseTo(0.016, 5);
    expect(cold.breakdown.context).toBeCloseTo(0.32, 5);
    expect(cold.usd).toBeGreaterThan(warm.usd * 4);
    const ask = estimateTurn({ contextTokens: 80_000, warm: true, price: p, lean: true, mode: 'ask' });
    expect(ask.breakdown.toolCalls).toBe(0);
    // empty conversation still pays the base prompt
    expect(estimateTurn({ contextTokens: 0, warm: false, price: p, lean: true }).breakdown.context).toBeCloseTo(0.036, 5);
    expect(estimateTurn({ contextTokens: 0, warm: false, price: p, lean: false }).breakdown.context).toBeCloseTo(0.07, 5);
  });

  it('cold resume costs', () => {
    const c = coldResumeCosts(80_000, priceFor(S, 'sonnet'), true);
    expect(c.resumeCostUsd).toBeCloseTo(0.32, 4);
    expect(c.freshCostUsd).toBeCloseTo(0.046, 4);
    expect(coldResumeCosts(80_000, priceFor(S, 'opus'), true).resumeCostUsd).toBeCloseTo(0.64, 4);
  });

  it('cold-resume decision', () => {
    const base = { lastActivityAt: 1_000_000, contextTokens: 80_000, hasSession: true, convModel: 'sonnet', model: 'sonnet' };
    const at = (min: number) => 1_000_000 + min * MIN;
    expect(cacheState({ ...base, now: at(10) }, S)).toEqual({ idleMinutes: 10, warm: true, cold: false });
    expect(cacheState({ ...base, now: at(120) }, S)).toEqual({ idleMinutes: 120, warm: false, cold: true });
    expect(cacheState({ ...base, contextTokens: 20_000, now: at(120) }, S).cold).toBe(false); // small context
    expect(cacheState({ ...base, hasSession: false, now: at(120) }, S).cold).toBe(false); // nothing to resume
    expect(cacheState({ ...base, now: at(120) }, { ...S, coldResumeGuard: false }).cold).toBe(false); // switched off
    expect(cacheState({ ...base, model: 'opus', now: at(10) }, S).warm).toBe(false); // other model = other cache
    expect(cacheState({ ...base, lastActivityAt: null, now: at(10) }, S)).toEqual({ idleMinutes: null, warm: false, cold: false });
  });

  it('budget / turn-limit stops', () => {
    expect(limitStop('error_max_budget_usd', { maxBudgetUsd: 1 })).toEqual({ kind: 'budget', message: expect.stringContaining('($1.00)') });
    expect(limitStop('error_max_turns', { maxTurns: 30 })!.message).toContain('30 turns');
    expect(limitStop('api_error', {})).toBeNull();
  });

  it('summary builder: first + recent turns, files, open todos, hard cap', () => {
    const turns = Array.from({ length: 9 }, (_, i) => ({ user: `prompt ${i} ` + 'x'.repeat(400), assistant: `answer ${i} ` + 'y'.repeat(2000), status: 'done' }));
    const s = formatSummary({
      turns,
      files: ['index.html', 'style.css'],
      todos: [{ content: 'Add footer', status: 'pending' }, { content: 'Hero', status: 'completed' }],
    });
    expect(s).toContain('9 earlier turns');
    expect(s).toContain('prompt 0'); // first request kept
    expect(s).not.toContain('prompt 1 '); // older middle turns dropped
    expect(s).toContain('prompt 8');
    expect(s).toContain('Files changed so far: index.html, style.css');
    expect(s).toContain('[ ] Add footer');
    expect(s).not.toContain('Hero');
    expect(s.length).toBeLessThanOrEqual(SUMMARY_MAX_CHARS);
    expect(s.length / 4).toBeLessThan(2_500); // ≈ tokens
    expect(formatSummary({ turns: [], files: [], todos: [] })).toBe('');
    const big = formatSummary({ turns, files: Array.from({ length: 400 }, (_, i) => `dir/file-${i}-${'z'.repeat(80)}.js`), todos: [] });
    expect(big.length).toBeLessThanOrEqual(SUMMARY_MAX_CHARS);
    expect(relPath('/workspace/projects/site/src/a.js', '/workspace/projects', 'site')).toBe('src/a.js');
    expect(relPath('/workspace/projects/.branches/site/feat/a.js', '/workspace/projects', 'site')).toBe('a.js');
    expect(relPath('/workspace/projects/other/a.js', '/workspace/projects', null)).toBe('other/a.js');
  });

  it('lean system prompt is shorter and carries the frugality rules', () => {
    const p = { name: 'Site', slug: 'site', description: null, preview_port: 4100, preview_strip: 1 } as never;
    const cfg = { publicUrl: 'https://x', claudeboxProjectsDir: '/workspace/projects' } as never;
    const full = buildSystemPrompt(p, cfg, [], null, false);
    const lean = buildSystemPrompt(p, cfg, [], null, true);
    expect(lean).toContain('Edit existing files with Edit');
    expect(lean).toContain('Never paste code');
    expect(lean).toContain('only when you create the project');
    expect(lean).toContain('<nx-suggestions>');
    expect(full).toContain('Keep a concise, up-to-date README.md');
    expect(lean.length).toBeLessThan(full.length + 400);
  });
});

describe('efficiency: routes', () => {
  let env: TestEnv;
  let alice: string;
  let project: any;
  beforeAll(async () => {
    env = await makeEnv({}, { listen: true });
    await createUser(env, 'eff@test.local', 'eff-pass-123');
    alice = await login(env, 'eff@test.local', 'eff-pass-123');
    project = (await api(env, alice, 'POST', '/api/projects', { name: 'Eff' })).json;
  });
  afterAll(async () => env.close());

  const db = () => env.built.ctx.db;
  const run = (id: string) => db().prepare('SELECT * FROM runs WHERE id = ?').get(id) as any;
  const finished = async (id: string) => {
    for (let i = 0; i < 250; i++) {
      if (['done', 'error', 'aborted'].includes(run(id)?.status)) return run(id);
      await new Promise((r) => setTimeout(r, 20));
    }
    throw new Error('run did not finish');
  };
  const prompt = (convId: string, text: string, extra: Record<string, unknown> = {}) =>
    api(env, alice, 'POST', `/api/conversations/${convId}/prompt`, { text, model: 'sonnet', mode: 'auto', ...extra });

  it('cold resume: 409 with estimates, then resume / fresh (new session + summary)', async () => {
    const conv = (await api(env, alice, 'POST', `/api/projects/${project.id}/conversations`, {})).json;
    const r1 = await prompt(conv.id, 'Build the landing page');
    await finished(r1.json.runId);
    const c = db().prepare('SELECT * FROM conversations WHERE id = ?').get(conv.id) as any;
    expect(c.claude_session_id).toBe('sess-1');
    expect(c.last_activity_at).toBeGreaterThan(0);
    // warm: no prompt
    const est = await api(env, alice, 'GET', `/api/conversations/${conv.id}/estimate?model=sonnet`);
    expect(est.json.warm).toBe(true);
    expect(est.json.coldResume).toBeNull();
    expect(est.json.estimate.usd).toBeGreaterThan(0);
    // fake 2h idle + large context
    db().prepare('UPDATE conversations SET last_activity_at = ?, context_tokens = 80000 WHERE id = ?').run(Date.now() - 120 * MIN, conv.id);
    const est2 = await api(env, alice, 'GET', `/api/conversations/${conv.id}/estimate?model=sonnet`);
    expect(est2.json.coldResume).toMatchObject({ idleMinutes: 120, resumeCostUsd: 0.32 });
    const refused = await prompt(conv.id, 'And add a footer');
    expect(refused.status).toBe(409);
    expect(refused.json.error.code).toBe('cold_resume');
    expect(refused.json.error.details).toMatchObject({ contextTokens: 80000, resumeCostUsd: 0.32 });
    expect(refused.json.error.message).toContain('idle 2h');
    expect(db().prepare('SELECT COUNT(*) AS n FROM runs WHERE conversation_id = ?').get(conv.id)).toEqual({ n: 1 }); // nothing persisted

    const n = env.fake.bodies.length;
    const fresh = await prompt(conv.id, 'And add a footer', { resumeChoice: 'fresh' });
    expect(fresh.status).toBe(200);
    await finished(fresh.json.runId);
    const body = env.fake.bodies[n]!;
    expect(body.sessionId).toBeNull();
    expect(String(body.appendSystemPrompt)).toContain('Conversation so far (summary');
    expect(String(body.appendSystemPrompt)).toContain('Build the landing page');
    expect(run(fresh.json.runId)).toMatchObject({ resume_choice: 'fresh' });
    expect(run(fresh.json.runId).saved_usd).toBeGreaterThan(0.2);

    db().prepare('UPDATE conversations SET last_activity_at = ?, context_tokens = 80000 WHERE id = ?').run(Date.now() - 120 * MIN, conv.id);
    const resumed = await prompt(conv.id, 'One more thing', { resumeChoice: 'resume' });
    await finished(resumed.json.runId);
    expect(env.fake.bodies.at(-1)!.sessionId).toBe('sess-1');
    expect(String(env.fake.bodies.at(-1)!.appendSystemPrompt)).not.toContain('Conversation so far');

    const ov = await api(env, env.adminCookie ?? (await login(env, 'admin@test.local', 'admin-password-1')), 'GET', '/api/admin/overview');
    expect(ov.json.savings30d.coldResumesAvoided).toBe(1);
  });

  it('ask mode runs at low effort; lean off restores the old flags', async () => {
    const conv = (await api(env, alice, 'POST', `/api/projects/${project.id}/conversations`, {})).json;
    const r = await prompt(conv.id, 'What does index.html do?', { mode: 'ask' });
    await finished(r.json.runId);
    expect(env.fake.bodies.at(-1)).toMatchObject({ effort: 'low', lean: true, maxBudgetUsd: 1 });
    env.built.ctx.settings.update({ leanMode: false, maxBudgetUsd: { opus: 0, sonnet: 0, haiku: 0 } });
    const r2 = await prompt(conv.id, 'And style.css?', { mode: 'ask' });
    await finished(r2.json.runId);
    const b = env.fake.bodies.at(-1)!;
    expect(b).not.toHaveProperty('effort');
    expect(b).not.toHaveProperty('lean');
    expect(b).not.toHaveProperty('maxBudgetUsd');
    expect(String(b.appendSystemPrompt)).toContain('Keep a concise, up-to-date README.md');
    env.built.ctx.settings.update({ leanMode: true, maxBudgetUsd: DEFAULT_SETTINGS.maxBudgetUsd });
  });

  it('budget stop: friendly error + "Continue" suggestion; cost recorded', async () => {
    const conv = (await api(env, alice, 'POST', `/api/projects/${project.id}/conversations`, {})).json;
    const r = await prompt(conv.id, 'big job [budget]');
    const row = await finished(r.json.runId);
    expect(row.status).toBe('error');
    expect(row.error).toContain('cost limit ($1.00)');
    expect(row.cost_usd).toBeCloseTo(0.0215, 4);
    expect(row.cost_estimated).toBe(0);
    const msg = db().prepare(`SELECT suggestions FROM messages WHERE run_id = ? AND role = 'assistant'`).get(r.json.runId) as any;
    expect(JSON.parse(msg.suggestions)[0]).toEqual({ label: 'Continue', prompt: 'continue', kind: 'next' });
    const ev = db().prepare(`SELECT data FROM run_events WHERE run_id = ? AND type = 'error'`).get(r.json.runId) as any;
    expect(JSON.parse(ev.data)).toMatchObject({ code: 'error_max_budget_usd', limit: 'budget' });
  });

  it('runs without a result event get an estimated cost from usage', async () => {
    const conv = (await api(env, alice, 'POST', `/api/projects/${project.id}/conversations`, {})).json;
    const r = await prompt(conv.id, 'crash [noresult]');
    const row = await finished(r.json.runId);
    expect(row.status).toBe('error');
    // 1000×2 + 2000×10 + 50000×0.2 + 10000×4 = 72000 µ$
    expect(row.cost_usd).toBeCloseTo(0.072, 5);
    expect(row.cost_estimated).toBe(1);
    const dto = await api(env, alice, 'GET', `/api/runs/${r.json.runId}`);
    expect(dto.json.costEstimated).toBe(true);
  });

  it('admin settings: efficiency fields validate and persist', async () => {
    const admin = await login(env, 'admin@test.local', 'admin-password-1');
    const bad = await api(env, admin, 'PATCH', '/api/admin/settings', { maxBudgetUsd: { opus: 0.001, sonnet: 1, haiku: 1 } });
    expect(bad.status).toBe(400);
    const ok = await api(env, admin, 'PATCH', '/api/admin/settings', { coldResumeMinutes: 40, newChatHintTokens: 50000, prices: { ...DEFAULT_SETTINGS.prices, haiku: { input: 1, output: 5, cacheWrite: 2, cacheRead: 0.1 } } });
    expect(ok.status).toBe(200);
    expect(ok.json).toMatchObject({ coldResumeMinutes: 40, newChatHintTokens: 50000, leanMode: true });
    const me = await api(env, alice, 'GET', '/api/usage/me');
    expect(me.json.context.newChatHintTokens).toBe(50000);
    await api(env, admin, 'PATCH', '/api/admin/settings', { coldResumeMinutes: 55, newChatHintTokens: 60000 });
  });
});

