export interface DiffFile { path: string; status: 'added' | 'deleted' | 'modified'; additions: number; deletions: number; binary: boolean }
export interface DiffSummary { branch: string; base: string; files: DiffFile[]; additions: number; deletions: number }
export interface FileDiff { path: string; status: string; binary: boolean; original: string; modified: string; patch: string }
export type AgentModel = 'inherit' | 'haiku' | 'sonnet' | 'opus';
export interface Agent {
  id: string; slug: string; name: string; description: string; prompt: string;
  tools: string[] | null; model: AgentModel; scope: 'global' | 'project'; projectId: string | null;
  enabled: boolean; builtin: boolean; modified: boolean; canEdit?: boolean;
  createdAt: string; updatedAt: string;
}
export interface Attachment { id: string; filename: string; mime: string; size: number; url: string; thumbUrl?: string }
export interface Run {
  id: string; status: RunStatus; model: string; mode: Mode; startedAt: string; endedAt?: string | null;
  inputTokens: number; outputTokens: number; cacheRead: number; cacheWrite: number; costUsd: number; durationMs?: number | null;
  branch?: string | null; commitSha?: string | null; undoSha?: string | null;
  /** Nexus runs: focus mentions, whether post-run checkpoints are done, projects in scope */
  nexus?: { focus: string[]; checkpointed: boolean; projects: number };
}
export interface StoredEvent { seq: number; type: string; data: any }
export interface Message {
  id: string; conversationId: string; role: 'user' | 'assistant'; content: string; attachments: Attachment[];
  runId?: string | null; createdAt: string; userName?: string;
  run?: Run | null; events?: StoredEvent[]; suggestions?: Suggestion[];
  /** 'compact' = manual compaction (rendered as a divider, not a bubble) */
  kind?: 'compact';
  /** Nexus runs: `<nx-handoff>` suggestions and per-project checkpoints */
  handoffs?: NexusHandoff[]; nexusCommits?: NexusCommit[];
}
/** GET /api/nexus/scope */
export interface NexusScopeProject {
  id: string; slug: string; name: string; color: string; icon: string; description: string; parentId: string | null;
  branches: string[]; busy: boolean; tech: string; lastActiveAt: string | null;
}
