// Token-efficiency UI bits for the prompt box: pre-send estimate, cold-resume card, model-switch confirm.
import { useEffect, useState } from 'react';
import { Snowflake, Sparkles } from 'lucide-react';
import { api } from '@/lib/api';
import type { Conversation, CostEstimate, ModelPrice } from '@/lib/types';
import { useAuth } from '@/stores/auth';
import type { SendError, SendOpts } from './store';
import { fmtTokens } from './toolFormat';
import { Tip } from './ui';

// ---------- remembered cold-resume choice (per user, this browser) ----------
const prefKey = () => `nx:resumeChoice:${useAuth.getState().user?.id ?? 'anon'}`;
export function getResumePref(): SendOpts['resumeChoice'] | undefined {
  try { const v = localStorage.getItem(prefKey()); return v === 'fresh' || v === 'resume' ? v : undefined; } catch { return undefined; }
}
export function setResumePref(v: SendOpts['resumeChoice'] | null) {
  try { if (v) localStorage.setItem(prefKey(), v); else localStorage.removeItem(prefKey()); } catch { /* ignore */ }
}

export function fmtUsd(n: number | null | undefined): string {
  if (n == null || !Number.isFinite(n)) return '–';
  if (n < 0.01) return '<$0.01';
  return `$${n < 1 ? n.toFixed(2) : n.toFixed(2)}`;
}
const DEFAULT_PRICES: Record<string, ModelPrice> = {
  opus: { input: 4, output: 20, cacheWrite: 8, cacheRead: 0.2 },
  sonnet: { input: 2, output: 10, cacheWrite: 4, cacheRead: 0.2 },
  haiku: { input: 1, output: 5, cacheWrite: 2, cacheRead: 0.1 },
};
export function priceOf(model: string, prices?: CostEstimate['prices'] | null): ModelPrice {
  const m = model.toLowerCase();
  const fam = m.includes('opus') ? 'opus' : m.includes('haiku') ? 'haiku' : 'sonnet';
  return prices?.[fam] ?? DEFAULT_PRICES[fam];
}
/** Cost of re-writing `tokens` of context into a (cold) cache of `model`. */
export const rebuildCost = (tokens: number, model: string, prices?: CostEstimate['prices'] | null) => (tokens * priceOf(model, prices).cacheWrite) / 1e6;

/** Pre-send estimate for the active conversation (or a new chat); refreshed on changes and every minute. */
export function useCostEstimate(conv: Conversation | undefined, model: string, mode: string, nonce: unknown): CostEstimate | null {
  const [est, setEst] = useState<CostEstimate | null>(null);
  const [tick, setTick] = useState(0);
  useEffect(() => { const t = window.setInterval(() => setTick((x) => x + 1), 60_000); return () => window.clearInterval(t); }, []);
  const convId = conv?.id;
  useEffect(() => {
    let dead = false;
    const q = `model=${encodeURIComponent(model)}&mode=${encodeURIComponent(mode)}`;
    const t = window.setTimeout(() => {
      api.get<CostEstimate>(convId ? `/conversations/${convId}/estimate?${q}` : `/estimate?${q}`)
        .then((r) => { if (!dead) setEst(r); })
        .catch(() => { if (!dead) setEst(null); });
    }, 250);
    return () => { dead = true; window.clearTimeout(t); };
  }, [convId, model, mode, conv?.contextTokens, conv?.lastActivityAt, conv?.claudeSessionId, nonce, tick]);
  return est;
}

/** Subtle "~$0.02" in the prompt footer; hover shows the breakdown. */
export function CostEstimateBadge({ est }: { est: CostEstimate | null }) {
  if (!est) return null;
  const b = est.estimate.breakdown;
  const cold = !est.warm && est.contextTokens > 0;
  const label = (
    <div className="space-y-0.5 text-[11.5px] leading-snug">
      <div className="mb-1 text-ink">Estimated cost of the next message</div>
      <Row k={`Context ${fmtTokens(Math.max(est.contextTokens, 1))}${est.contextTokens ? (est.warm ? ' · cached' : ' · cache cold') : ' (base prompt)'}`} v={b.context} />
      <Row k="Your message" v={b.input} />
      <Row k="Typical reply" v={b.output} />
      {b.toolCalls > 0 && <Row k="~2 tool round-trips" v={b.toolCalls} />}
      <div className="pt-1 text-muted">
        {est.contextTokens === 0 ? 'New chat: only the base prompt is read.'
          : est.warm ? `Cache warm${est.idleMinutes != null ? ` (last reply ${est.idleMinutes} min ago, ~${Math.max(0, est.cacheMinutes - est.idleMinutes)} min left)` : ''}.`
            : 'Cache cold: the first call re-writes the whole context.'}
        {' '}Rough API-equivalent estimate.
      </div>
    </div>
  );
  return (
    <Tip label={label}>
      <span className={`inline-flex h-7 shrink-0 cursor-default items-center gap-1 rounded-lg px-1 font-mono text-[11px] ${cold ? 'text-warn/80' : 'text-muted/70'}`}>
        {cold && <Snowflake size={11} />}~{fmtUsd(est.estimate.usd)}
      </span>
    </Tip>
  );
}
function Row({ k, v }: { k: string; v: number }) {
  return <div className="flex justify-between gap-4"><span className="text-muted">{k}</span><span className="font-mono text-ink/90">{fmtUsd(v)}</span></div>;
}

/** Inline card for `409 cold_resume`: continue fresh (free summary) or resume the full history. */
export function ColdResumeCard({ err, busy, onChoose, onDismiss }: {
  err: SendError; busy: boolean; onChoose: (choice: 'fresh' | 'resume', remember: boolean) => void; onDismiss: () => void;
}) {
  const [remember, setRemember] = useState(false);
  const d = err.details ?? {};
  return (
    <div className="nxw-fade-in mb-2 rounded-xl border border-violet/35 bg-violet/[.07] px-3 py-2.5 text-[13px]">
      <div className="flex items-start gap-2">
        <Snowflake size={15} className="mt-0.5 shrink-0 text-violet" />
        <div className="min-w-0 flex-1 text-ink/90">{err.message}</div>
        <button type="button" onClick={onDismiss} className="shrink-0 text-[12px] text-muted hover:text-ink">✕</button>
      </div>
      <div className="mt-2 flex flex-wrap items-center gap-2 pl-6">
        <button type="button" disabled={busy} onClick={() => onChoose('fresh', remember)}
          className="inline-flex items-center gap-1.5 rounded-lg border border-violet/50 bg-violet/15 px-2.5 py-1 text-[12.5px] text-ink transition hover:bg-violet/25 disabled:opacity-50">
          <Sparkles size={12} /> Continue fresh{d.freshCostUsd != null ? ` (~${fmtUsd(d.freshCostUsd)})` : ''}
        </button>
        <button type="button" disabled={busy} onClick={() => onChoose('resume', remember)}
          className="rounded-lg border border-line px-2.5 py-1 text-[12.5px] text-muted transition hover:bg-white/5 hover:text-ink disabled:opacity-50">
          Resume anyway{d.resumeCostUsd != null ? ` (~${fmtUsd(d.resumeCostUsd)})` : ''}
        </button>
        <label className="ml-auto inline-flex cursor-pointer select-none items-center gap-1.5 text-[11.5px] text-muted">
          <input type="checkbox" checked={remember} onChange={(e) => setRemember(e.target.checked)} className="accent-[#ff3e8a]" />
          Remember my choice
        </label>
      </div>
    </div>
  );
}

